func (s *Service) Create(w http.ResponseWriter, r *http.Request) {
	name, ok := decodeName(w, r)
	if !ok {
		return
	}
	workspaceID := s.h.WorkspaceID(r)
	wsUUID, ok := handler.ParseUUIDOrBadRequest(w, workspaceID, "workspace_id")
	if !ok {
		return
	}
	userID, ok := handler.RequireUserID(w, r)
	if !ok {
		return
	}
	actorType, actorID := s.h.Actor(r, userID, workspaceID)
	creatorID, ok := handler.ParseUUIDOrBadRequest(w, actorID, "creator_id")
	if !ok {
		return
	}
	folder, err := s.q.CreateProjectFolder(r.Context(), folderdb.CreateProjectFolderParams{
		WorkspaceID: wsUUID,
		Name:        name,
		CreatorType: pgtype.Text{String: actorType, Valid: true},
		CreatorID:   creatorID,
	})
	if err != nil {
		if handler.IsUniqueViolation(err) {
			handler.WriteError(w, http.StatusConflict, "a folder with that name already exists")
			return
		}
		slog.Warn("CreateProjectFolder failed", append(logger.RequestAttrs(r), "error", err)...)
		handler.WriteError(w, http.StatusInternalServerError, "failed to create project folder")
		return
	}
	resp := folderToResponse(folder)
	s.h.Publish(EventCreated, workspaceID, actorType, actorID, map[string]any{"folder": resp})
	handler.WriteJSON(w, http.StatusCreated, resp)
}

func (s *IssueService) noteRuntimeUnusable(ctx context.Context, issue db.Issue, verdict AgentVerdict) {
	name := ""
	if agent, err := s.Queries.GetAgent(ctx, issue.AssigneeID); err == nil {
		name = agent.Name
	}
	// author_type='system', author_id=zero UUID. The zero UUID is a valid 16
	// byte value and the column is NOT NULL; clients branch on author_type.
	created, err := s.Queries.CreateComment(ctx, db.CreateCommentParams{
		ID:          dbid.NewV7(),
		IssueID:     issue.ID,
		WorkspaceID: issue.WorkspaceID,
		AuthorType:  "system",
		AuthorID:    pgtype.UUID{Valid: true},
		Content:     RuntimeUnusableNotice(name, verdict),
		Type:        "system",
		ParentID:    pgtype.UUID{Valid: false},
	})
	if err != nil {
		slog.Warn("runtime unusable notice: create system comment failed",
			"error", err, "issue_id", util.UUIDToString(issue.ID))
		return
	}
	comment := created.Comment()
	if s.Bus == nil {
		return
	}
	s.Bus.Publish(events.Event{
		Type:        protocol.EventCommentCreated,
		WorkspaceID: util.UUIDToString(issue.WorkspaceID),
		ActorType:   "system",
		Payload: map[string]any{
			"comment": map[string]any{
				"id":          util.UUIDToString(comment.ID),
				"issue_id":    util.UUIDToString(comment.IssueID),
				"author_type": comment.AuthorType,
				"author_id":   util.UUIDToString(comment.AuthorID),
				"content":     comment.Content,
				"type":        comment.Type,
				"revision":    comment.Revision,
			},
			"issue_title":    issue.Title,
			"issue_revision": created.IssueRevision,
		},
	})
}

func (h *Handler) publish(eventType, workspaceID, actorType, actorID string, payload any) {
	h.Bus.Publish(events.Event{
		Type:        eventType,
		WorkspaceID: workspaceID,
		ActorType:   actorType,
		ActorID:     actorID,
		Payload:     payload,
	})
}

func publish(pub Publisher, e events.Event) {
	// A service built without a bus holds a nil *events.Bus, which arrives
	// here as a non-nil interface.
	if pub == nil {
		return
	}
	if bus, ok := pub.(*events.Bus); ok && bus == nil {
		return
	}
	pub.Publish(e)
}

func (s *ChatWakeupService) publish(ctx context.Context, w db.ChatWakeup, taskID pgtype.UUID) {
	if s.Tasks.Bus == nil {
		return
	}
	payload := protocol.ChatWakeupChangedPayload{
		ChatSessionID: util.UUIDToString(w.ChatSessionID),
		WakeupID:      util.UUIDToString(w.ID),
		Status:        w.Status,
	}
	if taskID.Valid {
		payload.TaskID = util.UUIDToString(taskID)
	}
	session, err := s.Tasks.Queries.GetChatSession(ctx, w.ChatSessionID)
	if err != nil {
		return
	}
	s.Tasks.Bus.Publish(events.Event{
		Type:               protocol.EventChatWakeupChanged,
		WorkspaceID:        util.UUIDToString(w.WorkspaceID),
		ActorType:          "system",
		ChatSessionID:      util.UUIDToString(w.ChatSessionID),
		ChatSessionOwnerID: util.UUIDToString(session.CreatorID),
		Payload:            payload,
	})
}

