func (h *Handler) PutIssueViewPreference(w http.ResponseWriter, r *http.Request) {
	userID, ok := requireUserID(w, r)
	if !ok {
		return
	}
	wsUUID, ok := parseUUIDOrBadRequest(w, h.resolveWorkspaceID(r), "workspace id")
	if !ok {
		return
	}
	var req PutIssueViewPreferenceRequest
	r.Body = http.MaxBytesReader(w, r.Body, issueViewBodyMaxBytes)
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body")
		return
	}
	rawScopeID := ""
	if req.ScopeID != nil {
		rawScopeID = *req.ScopeID
	}
	scopeID, ok := h.resolvePreferenceScope(w, r, wsUUID, userID, req.ScopeType, rawScopeID)
	if !ok {
		return
	}
	if len(req.Prefs) == 0 {
		req.Prefs = json.RawMessage("{}")
	}
	if !isJSONObject(req.Prefs) {
		writeError(w, http.StatusBadRequest, "prefs must be a JSON object")
		return
	}

	pref, err := h.Queries.UpsertIssueViewPreference(r.Context(), db.UpsertIssueViewPreferenceParams{
		WorkspaceID: wsUUID,
		UserID:      parseUUID(userID),
		ScopeType:   req.ScopeType,
		ScopeID:     scopeID,
		Prefs:       req.Prefs,
	})
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to save preference")
		return
	}
	h.Bus.Publish(events.Event{
		Type:                protocol.EventIssueViewPreferenceChanged,
		WorkspaceID:         uuidToString(wsUUID),
		ActorType:           "member",
		ActorID:             userID,
		MemberPrivateUserID: userID,
		Payload: map[string]any{
			"scope_type": pref.ScopeType,
			"scope_id":   uuidToPtr(pref.ScopeID),
		},
	})
	writeJSON(w, http.StatusOK, IssueViewPreferenceResponse{
		ScopeType: pref.ScopeType,
		ScopeID:   uuidToPtr(pref.ScopeID),
		Prefs:     json.RawMessage(pref.Prefs),
		UpdatedAt: timestampToString(pref.UpdatedAt),
	})
}

func (h *Handler) publishIssueViewChanged(view db.IssueView, wasShared bool, actorID, action string) {
	e := events.Event{
		Type:        protocol.EventIssueViewChanged,
		WorkspaceID: uuidToString(view.WorkspaceID),
		ActorType:   "member",
		ActorID:     actorID,
		Payload: map[string]any{
			"view_id": uuidToString(view.ID),
			"action":  action,
		},
	}
	if !wasShared && view.Visibility != "workspace" {
		e.MemberPrivateUserID = uuidToString(view.OwnerID)
	}
	h.Bus.Publish(e)
}

func (s *Service) Delete(w http.ResponseWriter, r *http.Request) {
	idUUID, ok := handler.ParseUUIDOrBadRequest(w, chi.URLParam(r, "id"), "folder id")
	if !ok {
		return
	}
	workspaceID := s.h.WorkspaceID(r)
	wsUUID, ok := handler.ParseUUIDOrBadRequest(w, workspaceID, "workspace_id")
	if !ok {
		return
	}
	userID, ok := handler.RequireUserID(w, r)
	if !ok {
		return
	}
	tx, err := s.h.TxStarter.Begin(r.Context())
	if err != nil {
		handler.WriteError(w, http.StatusInternalServerError, "failed to start transaction")
		return
	}
	defer tx.Rollback(r.Context())
	qtx := s.q.WithTx(tx)
	if _, err := qtx.DeleteProjectFolder(r.Context(), folderdb.DeleteProjectFolderParams{
		ID: idUUID, WorkspaceID: wsUUID,
	}); err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			handler.WriteError(w, http.StatusNotFound, "project folder not found")
			return
		}
		slog.Warn("DeleteProjectFolder failed", append(logger.RequestAttrs(r), "error", err)...)
		handler.WriteError(w, http.StatusInternalServerError, "failed to delete project folder")
		return
	}
	if err := qtx.ClearProjectFolder(r.Context(), folderdb.ClearProjectFolderParams{
		WorkspaceID: wsUUID, FolderID: idUUID,
	}); err != nil {
		handler.WriteError(w, http.StatusInternalServerError, "failed to move projects out of the folder")
		return
	}
	if err := tx.Commit(r.Context()); err != nil {
		handler.WriteError(w, http.StatusInternalServerError, "failed to commit project folder deletion")
		return
	}
	actorType, actorID := s.h.Actor(r, userID, workspaceID)
	s.h.Publish(EventDeleted, workspaceID, actorType, actorID, map[string]any{"folder_id": util.UUIDToString(idUUID)})
	w.WriteHeader(http.StatusNoContent)
}

func (p *PassthroughHeartbeatScheduler) Schedule(ctx context.Context, runtimeID, workspaceID pgtype.UUID) error {
	rows, err := p.queries.TouchAgentRuntimeLastSeen(ctx, runtimeID)
	if err != nil {
		return err
	}
	if rows > 0 {
		return nil
	}
	// The row either raced offline or was deleted. The conditional update
	// reports an actual offline → online flip so the recovery refresh can fire;
	// if another heartbeat already won the race (or the row is gone), the
	// unconditional MarkAgentRuntimeOnline still bumps last_seen_at and
	// preserves pgx.ErrNoRows for the deleted case.
	flipped, err := p.queries.MarkAgentRuntimeOnlineIfOffline(ctx, runtimeID)
	if err != nil {
		return err
	}
	if flipped > 0 {
		p.notifyRuntimeRecovered(ctx, workspaceID)
		return nil
	}
	_, err = p.queries.MarkAgentRuntimeOnline(ctx, runtimeID)
	return err
}

func (b *BatchedHeartbeatScheduler) Schedule(_ context.Context, runtimeID, _ pgtype.UUID) error {
	b.mu.Lock()
	b.pending[runtimeID] = struct{}{}
	b.mu.Unlock()
	return nil
}

func (b *pendingBatcher) Schedule(key string, flush func()) {
	b.schedule(key, flush, true)
}

func (b *BatchedHeartbeatScheduler) Run(ctx context.Context) {
	defer close(b.doneCh)
	t := time.NewTicker(b.tickInterval)
	defer t.Stop()
	for {
		select {
		case <-b.stopCh:
			// Drain whatever is still queued. Use a fresh, short-bounded
			// context so a cancelled parent ctx doesn't drop the final flush.
			drainCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
			b.flushOnce(drainCtx)
			cancel()
			return
		case <-ctx.Done():
			drainCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
			b.flushOnce(drainCtx)
			cancel()
			return
		case <-t.C:
			b.flushOnce(ctx)
		}
	}
}

func (m *Manager) Run(ctx context.Context) error {
	m.logger.Info("scheduler starting",
		"tick_interval", m.opts.TickInterval.String(),
		"jobs", len(m.snapshot()))

	// First tick immediately so a fresh start does not wait a full
	// interval; backoff to TickInterval thereafter.
	if err := m.RunOnce(ctx); err != nil && !errors.Is(err, context.Canceled) {
		m.logger.Warn("scheduler tick error", "error", err)
	}

	t := time.NewTicker(m.opts.TickInterval)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			m.logger.Info("scheduler stopped", "reason", ctx.Err())
			return ctx.Err()
		case <-t.C:
			if err := m.RunOnce(ctx); err != nil && !errors.Is(err, context.Canceled) {
				m.logger.Warn("scheduler tick error", "error", err)
			}
		}
	}
}

func (w *Worker) Run(ctx context.Context) {
	if !w.Enabled() {
		return
	}
	ticker := time.NewTicker(w.reconcileInterval)
	defer ticker.Stop()
	for {
		if err := w.ReconcileOnce(ctx); err != nil && ctx.Err() == nil {
			w.logger.WarnContext(ctx, "seat capacity outbox reconciliation failed", "error", err)
		}
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
		}
	}
}

func (m *TypingIndicatorManager) Run(ctx context.Context) {
	ticker := time.NewTicker(30 * time.Second)
	defer ticker.Stop()
	for {
		m.maintainCleanup(ctx)
		passCtx, cancel := context.WithTimeout(ctx, 10*time.Second)
		m.Reconcile(passCtx, pgtype.UUID{})
		cancel()
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
		}
	}
}

func (w *InstallWorker) Run(ctx context.Context) {
	if w == nil {
		return
	}
	if w.svc == nil {
		return
	}
	pollT := time.NewTicker(w.pollInterval)
	defer pollT.Stop()
	purgeT := time.NewTicker(w.purgeInterval)
	defer purgeT.Stop()

	// Immediately drain on start.
	w.drain(ctx)

	for {
		select {
		case <-ctx.Done():
			return
		case <-purgeT.C:
			if err := w.purge(ctx); err != nil && !errors.Is(err, context.Canceled) {
				w.svc.cfg.Logger.Warn("wecom install worker: purge", "error", err)
			}
		case <-pollT.C:
			w.drain(ctx)
		case <-w.wake:
			w.drain(ctx)
		}
	}
}

func (s *Supervisor) Run(ctx context.Context) {
	defer close(s.stopChan)

	// First sweep immediately so a freshly-restarted server doesn't wait a
	// full PollInterval before picking up its installations.
	s.sweep(ctx)

	t := time.NewTicker(s.cfg.PollInterval)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			s.cancelAll()
			return
		case <-t.C:
			s.sweep(ctx)
		case <-s.notify:
			s.sweep(ctx)
		}
	}
}

func (b *Bridge) Run(ctx context.Context) error {
	var err error
	if b.cfg.LoadState == nil {
		if err = os.MkdirAll(b.cfg.StateDir, 0700); err != nil {
			return err
		}
		lock, err := lockState(filepath.Join(b.cfg.StateDir, "bridge.lock"))
		if err != nil {
			return err
		}
		defer lock.Close()
	}
	binding := Binding(b.workpal.base, b.cfg.WorkspaceID, b.qoder.base, b.cfg.EnvironmentID)
	if b.cfg.SaveState != nil {
		binding = Binding("", b.cfg.WorkspaceID, b.qoder.base, b.cfg.EnvironmentID)
	}
	if b.cfg.LoadState != nil {
		var raw []byte
		raw, err = b.cfg.LoadState(ctx)
		if err == nil {
			b.state, err = decodeJournal(raw, binding)
		}
	} else {
		b.state, err = readJournal(b.path, binding)
	}
	if err != nil {
		return err
	}
	// Validate remote access before accepting work. Existing runs still reconcile
	// even if the live agent/environment was removed after the session snapshot.
	if len(b.state.Runs) == 0 {
		if err := b.Check(ctx); err != nil {
			return err
		}
	}

	// A stable daemon identity reconnects to the same runtime registration.
	if err = b.register(ctx, binding); err != nil {
		return err
	}
	if err = b.persist(); err != nil {
		return err
	}
	b.log.InfoContext(ctx, "Qoder runtime registered", "runtime_id", b.state.RuntimeID)
	if b.cfg.OnReady != nil {
		if err := b.cfg.OnReady(ctx, b.state.RuntimeID); err != nil {
			return err
		}
	}
	ticker := time.NewTicker(b.cfg.PollInterval)
	defer ticker.Stop()
	for {
		if err := ctx.Err(); err != nil {
			return nil
		}
		b.cleanup(ctx)
		// Heartbeats run even while event delivery or submission reconciliation is failing.
		if err := b.workpal.call(ctx, http.MethodPost, "/api/daemon/heartbeat", map[string]any{"runtime_id": b.state.RuntimeID}, nil); err != nil {
			b.log.WarnContext(ctx, "runtime heartbeat failed", "error", err)
			var denied *apiError
			if errors.As(err, &denied) && (denied.Status == 401 || denied.Status == 403 || denied.Status == 404) {
				if cancelErr := b.cancelActive(ctx); cancelErr != nil {
					b.log.WarnContext(ctx, "waiting to stop remote work after runtime access was lost", "error", cancelErr)
					select {
					case <-ctx.Done():
						return nil
					case <-ticker.C:
						continue
					}
				}
				return fmt.Errorf("runtime access lost: %w", err)
			}
		} else if err := b.guardedStep(ctx); err != nil {
			if errors.Is(err, context.Canceled) {
				return nil
			}
			var diskErr *persistenceError
			if errors.As(err, &diskErr) {
				return err
			}
			b.log.WarnContext(ctx, "Qoder bridge will retry reconciliation", "error", err)
		}
		select {
		case <-ctx.Done():
			return nil
		case <-ticker.C:
		}
	}
}

func (r *ChannelMediaReconciler) Run(ctx context.Context) {
	ticker := time.NewTicker(channelMediaReconcileSweepInterval)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			r.RunOnce(ctx)
		}
	}
}

func (h *Handler) recordHeartbeatState(
	ctx context.Context,
	runtimeUUID pgtype.UUID,
	runtimeID string,
	state heartbeatLivenessState,
	markDBWriteScheduled func(time.Time),
) error {
	now := time.Now()

	// Decide whether the DB row needs a write *before* touching Redis, so a
	// Touch failure can simply force needDBWrite=true without re-evaluating
	// the structural reasons.
	needDBWrite := !h.LivenessStore.Available() ||
		state.Status != "online" ||
		!state.LastSeenAtValid ||
		now.Sub(state.LastSeenAt) >= runtimeHeartbeatDBFlushInterval

	if h.LivenessStore.Available() {
		if err := h.LivenessStore.Touch(ctx, runtimeID, runtimeLivenessTTL); err != nil {
			// Redis hiccup: degrade transparently to the DB-only path for
			// this beat. The sweeper falls back to its DB threshold the
			// same way when IsAliveBatch fails, so end-to-end correctness
			// is preserved.
			slog.Warn("liveness touch failed; falling back to DB heartbeat",
				"runtime_id", runtimeID, "error", err)
			needDBWrite = true
		}
	}

	if !needDBWrite {
		return nil
	}

	// Status transitions remain synchronous so the acknowledgement cannot race
	// dependent work that expects an online row. The steady-state online bump
	// is ID-only and may be coalesced by the production scheduler.
	if state.Status != "online" || !state.LastSeenAtValid {
		// The conditional update reports whether this beat performed the
		// offline → online flip. Only an actual flip publishes the lifecycle
		// refresh; a beat that lost the race (or a never-seen row already
		// online) stays silent and keeps the unconditional update below so
		// last_seen_at is bumped and pgx.ErrNoRows is preserved for deletions.
		flipped, err := h.Queries.MarkAgentRuntimeOnlineIfOffline(ctx, runtimeUUID)
		if err != nil {
			return err
		}
		if flipped > 0 {
			// Reuse daemon:register so web and mobile invalidate both runtime and
			// agent projections. Ordinary online heartbeats stay silent.
			if state.WorkspaceID.Valid {
				h.PublishRuntimeRefresh(uuidToString(state.WorkspaceID), "system", "", "heartbeat_recovery")
			}
		} else if _, err := h.Queries.MarkAgentRuntimeOnline(ctx, runtimeUUID); err != nil {
			return err
		}
		if markDBWriteScheduled != nil {
			markDBWriteScheduled(now)
		}
		return nil
	}
	if err := h.HeartbeatScheduler.Schedule(ctx, runtimeUUID, state.WorkspaceID); err != nil {
		return err
	}
	if markDBWriteScheduled != nil {
		markDBWriteScheduled(now)
	}
	return nil
}

