func (h *Handler) ReportTaskUsage(w http.ResponseWriter, r *http.Request) {
	taskID := chi.URLParam(r, "taskId")

	// Verify the caller owns this task's workspace.
	task, workspaceID, ok := h.requireDaemonTaskAccessWithWorkspace(w, r, taskID)
	if !ok {
		return
	}

	var req struct {
		Usage []TaskUsagePayload `json:"usage"`
		// Snapshot marks a mid-run cumulative report from a daemon that meters
		// while its agent works (STOE-30). The rows are upserted identically —
		// UpsertTaskUsage overwrites per (task_id, provider, model), so a
		// snapshot can never add up twice — but the additive metrics counter and
		// the per-run cache-ratio log stay on the terminal report: summing each
		// cumulative snapshot into RecordLLMUsage would bill the same tokens
		// once per flush.
		Snapshot bool `json:"snapshot"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body")
		return
	}

	// Provider is lowercased on write so client-side pricing lookups tolerate
	// case drift. An empty provider (an older daemon that omits the field) is
	// stamped from the task's runtime, so generic model ids like `auto` still
	// resolve to a provider instead of landing as '' and pricing $0.
	var runtimeProvider string
	runtimeProviderLoaded := false
	updated := false
	for _, u := range req.Usage {
		provider := normalizeProvider(u.Provider)
		if provider == "" {
			if !runtimeProviderLoaded {
				if rt, err := h.getAgentRuntime(r.Context(), obsmetrics.RuntimeLookupSourceTask, task.RuntimeID); err == nil {
					runtimeProvider = normalizeProvider(rt.Provider)
				} else {
					slog.Warn("load runtime provider for usage backfill failed",
						"task_id", taskID, "runtime_id", uuidToString(task.RuntimeID), "error", err)
				}
				runtimeProviderLoaded = true
			}
			provider = runtimeProvider
		}
		if err := h.Queries.UpsertTaskUsage(r.Context(), db.UpsertTaskUsageParams{
			TaskID:           task.ID,
			Provider:         provider,
			Model:            u.Model,
			InputTokens:      u.InputTokens,
			OutputTokens:     u.OutputTokens,
			CacheReadTokens:  u.CacheReadTokens,
			CacheWriteTokens: u.CacheWriteTokens,
			CostUsdTicks:     authoritativeCostTicks(u.CostUSDTicks),
			CreditsMicros:    reportedCredits(u.CreditsMicros),
		}); err != nil {
			slog.Warn("upsert task usage failed", "task_id", taskID, "model", u.Model, "error", err)
			continue
		}
		updated = true
		// A snapshot reports the run's total so far, so it is not a new charge:
		// RecordLLMUsage adds, and each flush would bill the tokens the previous
		// flush already billed. The terminal report carries them once.
		if !req.Snapshot {
			h.TaskService.CaptureTaskUsage(r.Context(), task, provider, u.Model, u.InputTokens, u.OutputTokens, u.CacheReadTokens, u.CacheWriteTokens, u.CostUSDTicks)
		}

		// Surface prompt-cache effectiveness per run so cache hit rates are
		// observable in logs, not just queryable from runtime_usage. The ratio
		// is cached input over total input-side tokens; a persistently low
		// value flags a prompt prefix that is not being reused across runs
		// (e.g. volatile values poisoning the cacheable prefix). MUL-3887.
		if !req.Snapshot {
			if totalInput := u.InputTokens + u.CacheReadTokens + u.CacheWriteTokens; totalInput > 0 {
				slog.Info("task prompt-cache usage",
					"task_id", taskID,
					"provider", provider,
					"model", u.Model,
					"input_tokens", u.InputTokens,
					"output_tokens", u.OutputTokens,
					"cache_read_tokens", u.CacheReadTokens,
					"cache_write_tokens", u.CacheWriteTokens,
					"cache_read_ratio", float64(u.CacheReadTokens)/float64(totalInput),
				)
			}
		}
	}

	if updated {
		// This invalidates the existing task and issue-usage queries without
		// broadcasting token counts or changing task progress/status.
		h.Bus.Publish(events.Event{
			Type:        protocol.EventTaskUsage,
			WorkspaceID: workspaceID,
			ActorType:   "system",
			TaskID:      uuidToString(task.ID),
			Payload:     protocol.TaskUsageUpdatedPayload{TaskID: uuidToString(task.ID)},
		})
	}

	writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
}

func (c *Client) FailTask(ctx context.Context, taskID, errMsg, sessionID, workDir, branchName, failureReason string, sessionRolloutMissing bool, retiredSessionID, durableWorkDir string) error {
	return c.failTaskWithRetrySchedule(ctx, taskID, errMsg, sessionID, workDir, branchName, failureReason, sessionRolloutMissing, retiredSessionID, durableWorkDir, defaultTerminalRetrySchedule)
}

func (h *Handler) ReportTaskMessages(w http.ResponseWriter, r *http.Request) {
	taskID := chi.URLParam(r, "taskId")

	var req TaskMessageBatchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid request body")
		return
	}
	if len(req.Messages) == 0 {
		writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
		return
	}

	// Verify the caller owns this task's workspace. The access check already
	// resolves the workspace id (it needs it to authorize the daemon), so take
	// it from there instead of re-running GetIssue / GetChatSession: this
	// endpoint fires every 500ms for every running task, and that second
	// lookup was a whole extra query per batch on the hottest write path in
	// the system (MUL-6523).
	task, scope, ok := h.requireDaemonTaskAccessWithScope(w, r, taskID)
	if !ok {
		return
	}

	// Broadcast reach is deliberately unchanged: only issue- and chat-backed
	// tasks streamed live messages before, and widening that to autopilot /
	// quick-create tasks is a product decision, not part of this optimization.
	workspaceID := ""
	if task.IssueID.Valid || task.ChatSessionID.Valid {
		workspaceID = scope.WorkspaceID
	}

	// Column-wise parameters for the single batch insert below. Building them
	// as parallel arrays rather than as one JSON document is deliberate: these
	// strings were just decoded out of the request, and re-encoding content /
	// output into JSON would make the server escape every byte a second time
	// and Postgres parse the envelope back out — measurably worse on exactly
	// the large messages that are already the most expensive (MUL-6523). Empty
	// string means SQL NULL, applied by the query's NULLIF.
	n := len(req.Messages)
	params := db.CreateTaskMessagesParams{
		TaskID:   task.ID,
		Ids:      make([]pgtype.UUID, 0, n),
		Seqs:     make([]int32, 0, n),
		Types:    make([]string, 0, n),
		Tools:    make([]string, 0, n),
		CallIds:  make([]string, 0, n),
		Contents: make([]string, 0, n),
		Inputs:   make([]string, 0, n),
		Outputs:  make([]string, 0, n),
		// Optional for mixed-version rollout. Older daemons omit the event
		// timestamp, and one missing or implausible value makes the whole batch
		// use database time so paired events never mix clocks.
		CreatedAts: make([]string, 0, n),
		// Tri-state through a text[]: "" is NULL, matching how the query maps
		// every other nullable column in this batch.
		OutputTruncations: make([]string, 0, n),
	}
	createdAts := taskMessageCreatedAts(req.Messages, time.Now().UTC())
	for i, msg := range req.Messages {
		if len(msg.IdempotencyKey) > 512 {
			writeError(w, http.StatusBadRequest, "message idempotency_key exceeds 512 bytes")
			return
		}
		var id uuid.UUID
		if msg.IdempotencyKey != "" {
			id = uuid.NewSHA1(uuid.UUID(task.ID.Bytes), []byte(msg.IdempotencyKey))
		} else {
			var err error
			id, err = uuid.NewV7()
			if err != nil {
				slog.Error("failed to generate task message id", "task_id", taskID, "error", err)
				writeError(w, http.StatusInternalServerError, "failed to persist task message")
				return
			}
		}

		// Redact sensitive information before persisting or broadcasting.
		msg.Content = redact.Text(msg.Content)
		msg.Output = redact.Text(msg.Output)
		msg.Input = redact.InputMap(msg.Input)

		// redact.Text only masks secret-shaped substrings; it has no opinion on
		// bytes PostgreSQL refuses to store. Tool output is the likeliest
		// carrier of a stray NUL in the whole system — an agent that cats a
		// binary, or a Windows tool emitting UTF-16 — and this endpoint has no
		// retry on the daemon side, so an unsanitized batch is silently lost
		// (GH #7098). Input is a JSONB column, so it needs the deep walk: the
		// offending byte can sit at any depth of a tool's arguments. Batching
		// raises the stakes: one bad byte now fails the whole statement rather
		// than a single row, which is inherent to one-statement writes.
		msg.Type = util.SanitizeTextForPostgres(msg.Type)
		msg.Tool = util.SanitizeTextForPostgres(msg.Tool)
		msg.CallID = util.SanitizeTextForPostgres(msg.CallID)
		msg.Content = util.SanitizeTextForPostgres(msg.Content)
		msg.Output = util.SanitizeTextForPostgres(msg.Output)
		if msg.Input != nil {
			if cleaned, ok := util.SanitizeJSONForPostgres(msg.Input).(map[string]any); ok {
				msg.Input = cleaned
			}
		}

		inputJSON := ""
		if msg.Input != nil {
			// Fail loud rather than dropping the field: a tool call whose
			// arguments silently vanish is worse than a 500 the daemon logs,
			// because the transcript then shows a tool_use with no input and
			// nothing anywhere records that it was lost.
			encoded, err := json.Marshal(msg.Input)
			if err != nil {
				slog.Error("failed to encode task message input", "task_id", taskID, "seq", msg.Seq, "error", err)
				writeError(w, http.StatusInternalServerError, "failed to persist task message")
				return
			}
			inputJSON = string(encoded)
		}

		params.Ids = append(params.Ids, pgtype.UUID{Bytes: [16]byte(id), Valid: true})
		params.Seqs = append(params.Seqs, int32(msg.Seq))
		params.Types = append(params.Types, msg.Type)
		params.Tools = append(params.Tools, msg.Tool)
		params.CallIds = append(params.CallIds, msg.CallID)
		params.Contents = append(params.Contents, msg.Content)
		params.Inputs = append(params.Inputs, inputJSON)
		params.Outputs = append(params.Outputs, msg.Output)
		params.CreatedAts = append(params.CreatedAts, createdAts[i])
		params.OutputTruncations = append(params.OutputTruncations, boolArrayElement(msg.OutputTruncated))
	}

	created, err := h.Queries.CreateTaskMessages(r.Context(), params)
	if err != nil {
		slog.Error("failed to create task messages", "task_id", taskID, "count", n, "error", err)
		writeError(w, http.StatusInternalServerError, "failed to persist task message")
		return
	}

	if workspaceID != "" {
		// CreateTaskMessages orders its result by seq, which is the daemon's
		// own within-batch ordering — so this publishes in the same order the
		// per-message loop did. A bare INSERT ... RETURNING has no row-order
		// guarantee, and subscribers render these events as they arrive, so the
		// ordering lives in the query rather than in the clients.
		chatSessionID := ""
		if task.ChatSessionID.Valid {
			chatSessionID = uuidToString(task.ChatSessionID)
		}
		for _, m := range created {
			// The ordered CTE makes sqlc name the row type after the query
			// rather than reusing the table model; the columns are the table's,
			// in order, so the conversion is checked by the compiler and breaks
			// loudly if the query ever stops returning the whole row.
			h.Bus.Publish(events.Event{
				Type:               protocol.EventTaskMessage,
				WorkspaceID:        workspaceID,
				ActorType:          "system",
				TaskID:             taskID,
				ChatSessionID:      chatSessionID,
				ChatSessionOwnerID: scope.ChatSessionOwnerID,
				Payload:            taskMessageToPayload(db.TaskMessage(m), taskID, uuidToString(task.IssueID)),
			})
		}
	}

	writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
}

func (w *WebhookDeliveryWorker) runLoop(ctx context.Context) {
	ticker := time.NewTicker(webhookWorkerPollInterval)
	defer ticker.Stop()
	for {
		worked, err := w.ProcessNext(ctx)
		if err != nil && !errors.Is(err, context.Canceled) {
			slog.Error("webhook worker: process delivery", "error", err)
		}
		if worked {
			continue
		}
		select {
		case <-ctx.Done():
			return
		case <-w.notify:
		case <-ticker.C:
		}
	}
}

func (h *Handler) handlePullRequestEvent(ctx context.Context, body []byte) {
	var p ghPullRequestPayload
	if err := json.Unmarshal(body, &p); err != nil {
		slog.Warn("github: bad pull_request payload", "err", err)
		return
	}
	if p.Installation.ID == 0 {
		return
	}
	insts, err := h.Queries.ListGitHubInstallationsByInstallationID(ctx, p.Installation.ID)
	if err != nil {
		slog.Warn("github: lookup installation failed", "err", err)
		return
	}
	if len(insts) == 0 {
		// Webhook from an installation we never wired up — nothing we
		// can attribute to a workspace, so drop it silently.
		return
	}
	// #4855 lets one GitHub App installation bind to several workspaces. A
	// repo's events belong to every bound workspace, so fan the delivery out:
	// each workspace independently mirrors the PR and auto-links it against its
	// own issues (its own prefix + github toggle). Repo scope is whatever GitHub
	// authorized the installation for; we deliberately don't gate on the
	// workspace.repos registry — that list is "code the agent clones", not a
	// webhook subscription (MUL-4343).
	//
	// Fanning out means an identifier can resolve in more than one workspace at
	// once (issue prefixes are not globally unique and issue numbers restart at
	// 1 per workspace, so two bound workspaces can both own a real "ABC-100").
	// Settle who — if anyone — may link each identifier BEFORE any workspace
	// writes, and treat that verdict as authoritative for the whole delivery.
	// See prLinkPolicy.
	linkPolicy := h.resolvePRLinkPolicy(ctx, insts, &p)
	for _, inst := range insts {
		h.mirrorPullRequestForWorkspace(ctx, inst.WorkspaceID, inst.InstallationID, &p, linkPolicy)
	}
	// The PR row(s) now carry the new head; ask the API pipeline for the
	// authoritative CI + mergeability snapshot for that head. The webhook is
	// only the doorbell — its own mergeable/checks payload is not used for
	// display anymore (MUL-5265).
	h.PRRefresh.Enqueue(p.Installation.ID, p.Repository.Owner.Login, p.Repository.Name, p.PullRequest.Number)
	if p.Action == "closed" && p.PullRequest.Merged {
		h.PRRefresh.RefreshConflictWatchers(ctx, p.Installation.ID, p.Repository.Owner.Login, p.Repository.Name, p.PullRequest.Number)
	}
}

func (h *Handler) triggerPRRefreshFromCIEvent(ctx context.Context, body []byte) {
	if !h.PRRefresh.Enabled() {
		return
	}
	var p ghCIEventPayload
	if err := json.Unmarshal(body, &p); err != nil {
		return
	}
	if p.Installation.ID == 0 || p.Repository.Name == "" {
		return
	}
	owner, repo := p.Repository.Owner.Login, p.Repository.Name

	seen := map[int32]struct{}{}
	enqueue := func(number int32) {
		if number == 0 {
			return
		}
		if _, ok := seen[number]; ok {
			return
		}
		seen[number] = struct{}{}
		h.PRRefresh.Enqueue(p.Installation.ID, owner, repo, number)
	}
	for _, pr := range p.CheckSuite.PullRequests {
		enqueue(pr.Number)
	}
	for _, pr := range p.CheckRun.PullRequests {
		enqueue(pr.Number)
	}
	if len(seen) > 0 {
		return
	}
	// No PR number in the payload (status event, or a check event whose
	// pull_requests array was empty) — resolve by head SHA.
	sha := p.SHA
	if sha == "" {
		sha = coalesce(p.CheckSuite.HeadSHA, p.CheckRun.CheckSuite.HeadSHA)
	}
	if sha == "" {
		return
	}
	numbers, err := h.Queries.ListGitHubPRNumbersByHeadSHA(ctx, db.ListGitHubPRNumbersByHeadSHAParams{
		InstallationID: p.Installation.ID,
		RepoOwner:      owner,
		RepoName:       repo,
		HeadSha:        sha,
	})
	if err != nil {
		return
	}
	for _, number := range numbers {
		enqueue(number)
	}
}

func pluginHookScheduleHandler(
	queries *db.Queries,
	plugins *service.PluginService,
	cache *pluginHookScheduleCache,
) Handler {
	return func(ctx context.Context, in HandlerInput) (HandlerResult, error) {
		scheduleID, generation, err := parsePluginHookScheduleScopeID(in.Scope.ID)
		if err != nil {
			return HandlerResult{}, fmt.Errorf("parse plugin hook schedule scope: %w", err)
		}
		if plugins == nil || !featureflags.PluginsV1Enabled(ctx, plugins.FeatureFlags) {
			return pluginHookScheduleSkipped("feature_disabled"), nil
		}

		row, err := queries.GetPluginHookSchedule(ctx, scheduleID)
		if err != nil {
			if errors.Is(err, pgx.ErrNoRows) {
				return pluginHookScheduleSkipped("schedule_not_found"), nil
			}
			return HandlerResult{}, fmt.Errorf("load plugin hook schedule: %w", err)
		}
		if !row.Enabled || row.Generation != generation {
			return pluginHookScheduleSkipped("schedule_generation_changed"), nil
		}

		installation, err := queries.GetPluginInstallation(ctx, row.InstallationID)
		if err != nil {
			if errors.Is(err, pgx.ErrNoRows) {
				return pluginHookScheduleSkipped("installation_not_found"), nil
			}
			return HandlerResult{}, fmt.Errorf("load plugin installation: %w", err)
		}
		if !installation.Enabled {
			return pluginHookScheduleSkipped("installation_disabled"), nil
		}
		hook, err := service.FindHook(installation, row.HookKey)
		if err != nil || hook.Schedule == nil ||
			!service.HookAllowsTrigger(hook, plugincontract.TriggerSchedule) ||
			hook.Transport.Type != plugincontract.TransportHTTP ||
			hook.Schedule.Cron != row.CronExpression || hook.Schedule.Timezone != row.Timezone {
			return pluginHookScheduleSkipped("manifest_changed"), nil
		}

		if plugins.HookBreakerOpen(ctx, installation.ID, hook.Key) {
			advancePluginHookNextRun(ctx, queries, row, in.PlanTime)
			result := pluginHookScheduleSkipped("circuit_open")
			result.Result["coalesced_occurrences"] = cache.takeCoalesced(in.Scope.ID, in.PlanTime)
			result.Result["dispatch_lag_ms"] = max(time.Since(in.PlanTime).Milliseconds(), 0)
			return result, nil
		}

		deliveryID := pluginHookScheduleDeliveryID(installation.ID, hook.Key, row.Generation, in.PlanTime)
		_, err = plugins.InvokeHook(ctx, service.HookInvocation{
			Installation: installation,
			Hook:         hook,
			Trigger:      plugincontract.TriggerSchedule,
			Actor:        service.HookActor{Type: "plugin", ID: installation.ID},
			DeliveryID:   deliveryID,
			PlannedAt:    pgtype.Timestamptz{Time: in.PlanTime.UTC(), Valid: true},
		}, in.Attempt)
		if err != nil {
			if in.Job != nil && in.Attempt >= in.Job.MaxAttempts {
				advancePluginHookNextRun(ctx, queries, row, in.PlanTime)
				cache.takeCoalesced(in.Scope.ID, in.PlanTime)
			}
			return HandlerResult{}, fmt.Errorf("deliver scheduled plugin hook: %w", err)
		}

		advancePluginHookNextRun(ctx, queries, row, in.PlanTime)
		return HandlerResult{RowsAffected: 1, Result: map[string]any{
			"delivery_id":           deliveryID,
			"coalesced_occurrences": cache.takeCoalesced(in.Scope.ID, in.PlanTime),
			"dispatch_lag_ms":       max(time.Since(in.PlanTime).Milliseconds(), 0),
		}}, nil
	}
}

func (m *Manager) runHeartbeats(
	ctx context.Context,
	done chan<- struct{},
	job *JobSpec,
	c claim,
	log *slog.Logger,
) {
	defer close(done)
	t := time.NewTicker(job.HeartbeatInterval)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-t.C:
			hbCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
			err := heartbeat(hbCtx, m.pool, c.ID, c.LeaseToken, job.StaleTimeout)
			cancel()
			if errors.Is(err, ErrLeaseLost) {
				log.Warn("scheduler: lease lost during heartbeat, runner should stop")
				return
			}
			if err != nil {
				log.Warn("scheduler: heartbeat error", "error", err)
			}
		}
	}
}

func (s *Supervisor) NodeID() string { return s.nodeID }

// Run is the Supervisor's main loop. It scans installations every
// PollInterval, attempts to lease any not currently supervised by this
// process, and reaps supervisors for installations that were revoked or
// whose lease was lost. Returns when ctx is cancelled; the caller MUST then
// call Wait to join all supervisor goroutines before exiting.
func (s *Supervisor) Run(ctx context.Context) {
	defer close(s.stopChan)

	// First sweep immediately so a freshly-restarted server doesn't wait a
	// full PollInterval before picking up its installations.
	s.sweep(ctx)

	t := time.NewTicker(s.cfg.PollInterval)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			s.cancelAll()
			return
		case <-t.C:
			s.sweep(ctx)
		case <-s.notify:
			s.sweep(ctx)
		}
	}
}

func (r *RedisRelay) heartbeatLoop(ctx context.Context) {
