func (c *Client) writePump() {
	ticker := time.NewTicker(pingPeriod)
	defer func() {
		ticker.Stop()
		c.conn.Close()
	}()

	for {
		select {
		case message, ok := <-c.send:
			if !ok {
				c.writeMu.Lock()
				if !c.stopped.Load() {
					c.conn.SetWriteDeadline(time.Now().Add(writeWait))
					c.conn.WriteMessage(websocket.CloseMessage, []byte{})
				}
				c.writeMu.Unlock()
				return
			}
			if !c.writeBatch(message) {
				return
			}
		case <-ticker.C:
			c.writeMu.Lock()
			if c.stopped.Load() {
				c.writeMu.Unlock()
				return
			}
			c.conn.SetWriteDeadline(time.Now().Add(writeWait))
			err := c.conn.WriteMessage(websocket.PingMessage, nil)
			c.writeMu.Unlock()
			if err != nil {
				return
			}
		}
	}
}

func (c *client) writePump() {
	ticker := time.NewTicker(pingPeriod)
	defer func() {
		ticker.Stop()
		c.conn.Close()
	}()

	for {
		select {
		case message, ok := <-c.send:
			c.conn.SetWriteDeadline(time.Now().Add(writeWait))
			if !ok {
				c.conn.WriteMessage(websocket.CloseMessage, []byte{})
				return
			}
			if err := c.conn.WriteMessage(websocket.TextMessage, message); err != nil {
				slog.Debug("daemon websocket write error", "error", err, "daemon_id", c.identity.DaemonID)
				return
			}
		case <-ticker.C:
			c.conn.SetWriteDeadline(time.Now().Add(writeWait))
			if err := c.conn.WriteMessage(websocket.PingMessage, nil); err != nil {
				return
			}
		}
	}
}

func (c *wsConnector) run(ctx context.Context) error {
	c.withDefaults()

	dialURL, err := c.open(ctx)
	if err != nil {
		return fmt.Errorf("dingtalk stream: open connection: %w", err)
	}
	conn, err := c.dialer.dial(ctx, dialURL)
	if err != nil {
		// dialURL carries the single-use Stream ticket. Dialer errors may echo
		// their input URL, so do not wrap them into the supervisor/log path.
		return fmt.Errorf("dingtalk stream: dial failed (%T)", err)
	}

	runCtx, cancel := context.WithCancel(ctx)

	var closeOnce sync.Once
	closeConn := func() { closeOnce.Do(func() { _ = conn.Close() }) }

	var writeMu sync.Mutex
	writeResponse := func(resp dataFrameResponse) error {
		b, err := json.Marshal(resp)
		if err != nil {
			return err
		}
		writeMu.Lock()
		defer writeMu.Unlock()
		_ = conn.SetWriteDeadline(time.Now().Add(c.writeTimeout))
		return conn.WriteMessage(websocket.TextMessage, b)
	}

	done := make(chan struct{})
	// Watchdog: gorilla's ReadMessage does not observe ctx, so closing the socket
	// is what unblocks a read stuck in the syscall when the run ctx is cancelled.
	go func() {
		select {
		case <-runCtx.Done():
			closeConn()
		case <-done:
		}
	}()

	pingDone := make(chan struct{})
	go func() {
		defer close(pingDone)
		ticker := time.NewTicker(c.pingInterval)
		defer ticker.Stop()
		for {
			select {
			case <-runCtx.Done():
				return
			case <-ticker.C:
				writeMu.Lock()
				err := conn.WriteControl(websocket.PingMessage, nil, time.Now().Add(c.writeTimeout))
				writeMu.Unlock()
				if err != nil {
					return // the read loop owns teardown
				}
			}
		}
	}()

	conn.SetPongHandler(func(string) error {
		return conn.SetReadDeadline(time.Now().Add(c.readDeadline))
	})

	defer func() {
		cancel()
		closeConn()
		close(done)
		<-pingDone
	}()

	for {
		if err := conn.SetReadDeadline(time.Now().Add(c.readDeadline)); err != nil {
			return fmt.Errorf("dingtalk stream: set read deadline: %w", err)
		}
		msgType, data, err := conn.ReadMessage()
		if err != nil {
			if runCtx.Err() != nil {
				return nil // ctx cancelled → graceful stop
			}
			return fmt.Errorf("dingtalk stream: read: %w", err)
		}
		if msgType != websocket.TextMessage {
			continue
		}
		var frame dataFrame
		if err := json.Unmarshal(data, &frame); err != nil {
			c.logger.WarnContext(runCtx, "dingtalk stream: malformed frame", "error", err)
			continue
		}

		switch {
		case frame.Type == frameTypeSystem && frame.topic() == systemTopicPing:
			if err := writeResponse(newPongResponse(frame.messageID(), frame.Data)); err != nil {
				if runCtx.Err() != nil {
					return nil
				}
				return fmt.Errorf("dingtalk stream: write pong: %w", err)
			}
		case frame.Type == frameTypeSystem && frame.topic() == systemTopicDisconnect:
			// Gateway asks us to reconnect; return cleanly and let the supervisor redial.
			return nil
		case frame.Type == frameTypeCallback && frame.topic() == botMessageTopic:
			c.dispatchCallback(runCtx, &frame, writeResponse)
		default:
			c.logger.WarnContext(runCtx, "dingtalk stream: unhandled frame",
				"type", frame.Type, "topic", frame.topic())
		}
	}
}

func (s *environmentService) run(ctx context.Context) {
	if s == nil {
		return
	}
	if err := s.manager.Load(); err != nil {
		s.logger.Warn("environments: load state failed", "error", err)
	}
	s.loadReported()
	ticker := time.NewTicker(environmentTickInterval)
	defer ticker.Stop()
	for tick := 0; ; tick++ {
		s.manager.Tick()
		if tick%environmentDetectEvery == 0 {
			s.detect(ctx)
		}
		s.report(ctx, time.Now())
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
		case <-s.wake:
			// A start or stop just happened; report it without detecting again.
			tick--
		}
	}
}

func (c *PostHogClient) run() {
	defer c.wg.Done()
	ticker := time.NewTicker(c.cfg.FlushEvery)
	defer ticker.Stop()

	batch := make([]Event, 0, c.cfg.BatchSize)
	flush := func() {
		if len(batch) == 0 {
			return
		}
		c.send(batch)
		batch = batch[:0]
	}

	for {
		select {
		case e := <-c.ch:
			batch = append(batch, e)
			if len(batch) >= c.cfg.BatchSize {
				flush()
			}
		case <-ticker.C:
			flush()
		case <-c.done:
			// Drain remaining events. The channel is not closed by Close() to
			// avoid racing with Capture, so we loop until it's empty.
			for {
				select {
				case e := <-c.ch:
					batch = append(batch, e)
					if len(batch) >= c.cfg.BatchSize {
						flush()
					}
				default:
					flush()
					return
				}
			}
		}
	}
}

func (m *Manager) MaybeEnqueueOnView(installationID int64, owner, repo string, number int32, fetchedAt time.Time, hasFetched bool) {
	if !m.Enabled() {
		return
	}
	if hasFetched && m.now().Sub(fetchedAt) < m.viewTTL {
		return
	}
	m.Enqueue(installationID, owner, repo, number)
}

func (m *Manager) scheduleRetry(addr address, delay time.Duration) {
	ctx := m.ctx
	time.AfterFunc(delay, func() {
		if ctx != nil && ctx.Err() != nil {
			return
		}
		m.Enqueue(addr.InstallationID, addr.Owner, addr.Repo, addr.Number)
	})
}

func (m *Manager) sweepLoop(ctx context.Context) {
	ticker := time.NewTicker(m.sweepInterval)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			m.sweepOnce(ctx)
		}
	}
}

func (m *Manager) sweepUndecided(ctx context.Context) {
	m.mu.Lock()
	after := m.sweepAfter
	m.mu.Unlock()

	rows, err := m.queries.ListStaleUndecidedGitHubPRs(ctx, db.ListStaleUndecidedGitHubPRsParams{
		OlderThan:           tsFromTime(m.now().Add(-m.sweepTTL)),
		AfterInstallationID: after.InstallationID,
		AfterRepoOwner:      after.Owner,
		AfterRepoName:       after.Repo,
		AfterPrNumber:       after.Number,
		MaxRows:             m.sweepMaxRows,
	})
	if err != nil {
		slog.Warn("ghsnapshot: sweep query failed", "err", err.Error())
		return
	}
	if len(rows) > 0 {
		last := rows[len(rows)-1]
		m.mu.Lock()
		m.sweepAfter = address{
			InstallationID: last.InstallationID,
			Owner:          last.RepoOwner,
			Repo:           last.RepoName,
			Number:         last.PrNumber,
		}
		m.mu.Unlock()
	}
	for _, r := range rows {
		m.Enqueue(r.InstallationID, r.RepoOwner, r.RepoName, r.PrNumber)
	}
}

func (m *Manager) sweepConflictWatched(ctx context.Context) {
	m.mu.Lock()
