func (s *IssueService) PublishAttachmentsChanged(ctx context.Context, issue db.Issue, actorID pgtype.UUID) {
	if s.Bus == nil {
		return
	}
	if s.Queries == nil {
		s.publishIssueAttachmentsChanged(issue, actorID, 0)
		return
	}

	current, err := s.Queries.GetIssueInWorkspace(ctx, db.GetIssueInWorkspaceParams{
		ID:          issue.ID,
		WorkspaceID: issue.WorkspaceID,
	})
	if err != nil {
		slog.Warn("failed to load issue after channel media bind",
			"issue_id", util.UUIDToString(issue.ID), "error", err)
		s.publishIssueAttachmentsChanged(issue, actorID, 0)
		return
	}
	workspace, err := s.Queries.GetWorkspace(ctx, issue.WorkspaceID)
	if err != nil {
		slog.Warn("failed to load workspace after channel media bind",
			"workspace_id", util.UUIDToString(issue.WorkspaceID), "error", err)
		// Without the workspace we cannot publish the matching owner snapshot.
		// Keep this auxiliary event unversioned so clients invalidate instead of
		// advancing the owner revision past a snapshot they never received.
		s.publishIssueAttachmentsChanged(issue, actorID, 0)
		return
	}
	s.Bus.Publish(events.Event{
		Type:        protocol.EventIssueUpdated,
		WorkspaceID: util.UUIDToString(issue.WorkspaceID),
		ActorType:   "member",
		ActorID:     util.UUIDToString(actorID),
		Payload: map[string]any{
			"issue":            IssueToMapResolved(ctx, s.Queries, current, workspace.IssuePrefix),
			"assignee_changed": false,
			"status_changed":   false,
			"project_changed":  false,
		},
	})
	// Publish the auxiliary projection only after the full owner snapshot at
	// this revision. Reversing these two events makes revision-aware clients
	// reject the issue:updated payload as an equal-revision duplicate.
	s.publishIssueAttachmentsChanged(current, actorID, current.Revision)
}

func (w *InstallWorker) finalizeSuccess(ctx context.Context, row db.WecomInstallSession, leaseToken string, bot *BotInfo) error {
	if bot == nil || strings.TrimSpace(bot.BotID) == "" || strings.TrimSpace(bot.Secret) == "" {
		w.failSession(ctx, row.ID, leaseToken, InstallErrorWecomProtocolError,
			"WeCom returned success without bot credentials")
		return nil
	}

	inst, err := w.svc.installations.Upsert(ctx, InstallationParams{
		WorkspaceID:     row.WorkspaceID,
		AgentID:         row.AgentID,
		InstallerUserID: row.InitiatorUserID,
		BotID:           bot.BotID,
		Secret:          bot.Secret,
	})
	if err != nil {
		// The bot exists on WeCom's side either way, so the session ends with a
		// reason the dialog can act on rather than retrying into the same
		// failure. Only a bot whose routing slot is held elsewhere is a
		// conflict. Anything else — the credential probe timing out, the
		// network, the database — is a bot that was created and could not be
		// connected, and calling it a conflict would send the admin looking
		// for a connection that does not exist.
		reason := InstallErrorBindFailed
		if bindConflict(err) {
			reason = InstallErrorInstallationConflict
		}
		w.svc.cfg.Logger.WarnContext(ctx, "wecom install: bind failed",
			"session_id", util.UUIDToString(row.ID), "reason", reason, "error", err)
		w.failSession(ctx, row.ID, leaseToken, reason,
			"Could not finalize the WeCom install: "+err.Error())
		return nil
	}

	rows, err := w.svc.store.CompleteWecomInstallSession(ctx, db.CompleteWecomInstallSessionParams{
		InstallationID: inst.ID,
		ID:             row.ID,
		LeaseToken:     pgtype.Text{String: leaseToken, Valid: true},
	})
	if err != nil {
		return fmt.Errorf("finalize: complete session: %w", err)
	}
	if rows == 0 {
		// Lost the lease mid-finalize: another worker owns this session and will
		// complete it. The Upsert above was idempotent, so nothing is left over.
		return nil
	}

	// Published only after the session is durably complete, so a failed
	// completion cannot fire a phantom installation-created event.
	if w.bus != nil {
		w.bus.Publish(events.Event{
			Type:        protocol.EventWecomInstallationCreated,
			WorkspaceID: util.UUIDToString(row.WorkspaceID),
			ActorType:   "system",
			ActorID:     util.UUIDToString(row.InitiatorUserID),
			Payload: map[string]any{
				"installation_id": util.UUIDToString(inst.ID),
				"agent_id":        util.UUIDToString(row.AgentID),
			},
		})
	}
	// Nudge the supervisor so the new bot's connection comes up now rather than
	// on the next installation scan.
	if w.supervisor != nil {
		w.supervisor.Notify()
	}
	w.svc.cfg.Logger.InfoContext(ctx, "wecom install: complete",
		"session_id", util.UUIDToString(row.ID),
		"installation_id", util.UUIDToString(inst.ID),
		"workspace_id", util.UUIDToString(row.WorkspaceID),
		"agent_id", util.UUIDToString(row.AgentID))
	return nil
}

func (r *Router) scheduleRunMode(
	set ResolverSet,
	inst ResolvedInstallation,
	msg channel.InboundMessage,
	sessionID, initiatorUserID, bindingID pgtype.UUID,
	routeRevision int64,
	fresh bool,
	contextRevision int64,
	replace bool,
	throughMessageID pgtype.UUID,
) {
	if r.batcher == nil {
		r.flushChatRun(
			set, inst, msg, sessionID, initiatorUserID, bindingID,
			routeRevision, fresh, contextRevision, throughMessageID,
		)
		return
	}
	key := keyForSessionContext(sessionID, contextRevision)
	flush := func() {
		// A later message in this same durable context generation may replace
		// the closure. /clear advances the generation and therefore uses a distinct
		// batch key; the pre-boundary flush remains armed independently.
		r.flushChatRun(
			set, inst, msg, sessionID, initiatorUserID, bindingID,
			routeRevision, fresh, contextRevision, throughMessageID,
		)
	}
	if replace {
		r.batcher.Schedule(key, flush)
	} else {
		r.batcher.ScheduleIfAbsent(key, flush)
	}
}

func RegisterWeixin(reg *channel.Registry, deps ChannelDeps) {
	reg.Register(TypeWeixin, func(cfg channel.Config) (channel.Channel, error) {
		creds, err := decodeCredentials(cfg.Raw, deps.Box)
		if err != nil {
			return nil, err
		}
		if deps.Queries == nil {
			return nil, errors.New("weixin: account store is required")
		}
		logger := deps.Logger
		if logger == nil {
			logger = slog.Default()
		}
		c := &weixinChannel{id: cfg.ID, config: cfg.Raw, creds: creds, api: newAPI(creds.BaseURL, creds.Token, deps.Client), q: deps.Queries, box: deps.Box, handler: cfg.Handler, logger: logger, typing: deps.Typing}
		if deps.Bus != nil {
			c.onExpired = func(ctx context.Context) {
				inst, err := deps.Queries.GetChannelInstallation(ctx, db.GetChannelInstallationParams{ID: cfg.ID, ChannelType: string(TypeWeixin)})
				if err == nil {
					deps.Bus.Publish(events.Event{Type: protocol.EventWeixinInstallationRevoked, WorkspaceID: util.UUIDToString(inst.WorkspaceID), ActorType: "system", Payload: map[string]any{"id": util.UUIDToString(inst.ID)}})
				}
			}
		}
		return c, nil
	})
}

func (n *TypingNotifier) keepalive(ctx context.Context, sessionID pgtype.UUID, inst db.ChannelInstallation, creds credentials, run *typingRun) {
	defer n.wg.Done()
	defer close(run.done)
	defer run.cancel()
	defer func() {
		n.mu.Lock()
		if n.runs[sessionID] == run {
			delete(n.runs, sessionID)
		}
		n.mu.Unlock()
	}()
	api := newAPI(creds.BaseURL, creds.Token, n.client)
	ticket := ""
	started := false
	defer func() {
		if ticket != "" {
			clear, cancel := context.WithTimeout(context.WithoutCancel(ctx), typingCallTimeout)
			defer cancel()
			if err := api.sendTyping(clear, creds.UserID, ticket, 2); err == nil {
				n.logger.Debug("weixin: typing stopped", "session_id", sessionID)
			}
		}
	}()
	ticker := time.NewTicker(n.interval)
	defer ticker.Stop()
	for {
		call, cancel := context.WithTimeout(ctx, typingCallTimeout)
		active, err := n.q.IsWeixinTypingActive(call, db.IsWeixinTypingActiveParams{InstallationID: inst.ID, ChatSessionID: sessionID, Config: inst.Config})
		if err != nil || !active {
			cancel()
			return
		}
		if ticket == "" {
			ticket = n.ticket(call, inst.ID, creds, api)
		}
		if ticket == "" {
			cancel()
			return
		}
		err = api.sendTyping(call, creds.UserID, ticket, 1)
		cancel()
		// Typing is cosmetic: a transient send failure must not end keepalives.
		if err == nil && !started {
			n.logger.DebugContext(ctx, "weixin: typing started", "session_id", sessionID)
			started = true
		}
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
		case <-run.wake:
		}
	}
}

