func (d *Daemon) gcLoop(ctx context.Context) {
	if !d.cfg.GCEnabled {
		d.logger.Info("gc: disabled")
		return
	}
	d.logger.Info("gc: started",
		"interval", d.cfg.GCInterval,
		"ttl", d.cfg.GCTTL,
		"completed_task_ttl", d.cfg.GCCompletedTaskTTL,
		"orphan_ttl", d.cfg.GCOrphanTTL,
		"artifact_ttl", d.cfg.GCArtifactTTL,
		"repo_ttl", d.cfg.GCRepoTTL,
		"repo_maintenance_enabled", d.cfg.GCRepoMaintenanceEnabled,
		"artifact_patterns", d.cfg.GCArtifactPatterns,
		"managed_artifact_subpaths", execenv.ManagedReclaimableArtifactSubpaths(),
	)

	// Run once at startup after a short delay (let the daemon finish initializing).
	if err := sleepWithContext(ctx, 30*time.Second); err != nil {
		return
	}
	d.runGC(ctx)

	ticker := time.NewTicker(d.cfg.GCInterval)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			d.runGC(ctx)
		}
	}
}

func (d *Daemon) autoUpdateLoop(ctx context.Context) {
	if d.cfg.LaunchedBy == "desktop" {
		d.logger.Info("auto-update: skipped (managed by Desktop)")
		return
	}

	pullEnabled := d.cfg.AutoUpdateEnabled
	switch {
	case !pullEnabled:
		d.logger.Info("auto-update: disabled")
	case !isReleaseVersion(d.cfg.CLIVersion):
		d.logger.Info("auto-update: skipped (not a release build)", "version", d.cfg.CLIVersion)
		pullEnabled = false
	}
	reloadEnabled := d.cfg.AutoReloadEnabled
	if !reloadEnabled {
		d.logger.Info("auto-reload: disabled")
	}
	if !pullEnabled && !reloadEnabled {
		return
	}

	pullInterval := d.cfg.AutoUpdateCheckInterval
	if pullInterval <= 0 {
		pullInterval = DefaultAutoUpdateCheckInterval
	}
	// Log what each half will do before the startup delay, so a user reading
	// daemon.log right after `daemon start` sees it immediately.
	if pullEnabled {
		d.logger.Info("auto-update: started", "interval", pullInterval, "current", d.cfg.CLIVersion)
	}
	if reloadEnabled {
		d.logger.Info("auto-reload: watching the workpal binary on disk",
			"interval", selfReloadCheckInterval, "current", d.cfg.CLIVersion)
	}

	if err := sleepWithContext(ctx, autoUpdateInitialDelay); err != nil {
		return
	}
	if pullEnabled {
		d.tryAutoUpdate(ctx)
	}
	if reloadEnabled {
		d.trySelfReload(ctx)
	}

	// Tickers start only now, after the first check. Starting them before the
	// delay would let an interval shorter than autoUpdateInitialDelay buffer a
	// tick and fire a second check immediately after the first.
	//
	// A disabled half leaves its channel nil, which never fires in a select.
	var pullTick, reloadTick <-chan time.Time
	if pullEnabled {
		ticker := time.NewTicker(pullInterval)
		defer ticker.Stop()
		pullTick = ticker.C
	}
	if reloadEnabled {
		ticker := time.NewTicker(selfReloadCheckInterval)
		defer ticker.Stop()
		reloadTick = ticker.C
	}

	for {
		select {
		case <-ctx.Done():
			return
		case <-pullTick:
			d.tryAutoUpdate(ctx)
		case <-reloadTick:
			d.trySelfReload(ctx)
		}
	}
}

func (d *Daemon) agentDiscoveryLoop(ctx context.Context) {
	ticker := time.NewTicker(agentDiscoveryInterval)
	defer ticker.Stop()
	versionTicker := time.NewTicker(agentVersionRefreshInterval)
	defer versionTicker.Stop()

	var (
		backoff   time.Duration
		nextRetry time.Time
		// lastMismatch is the DSH profile/runtime disagreement the previous tick
		// saw, for the one direction that is throttled to a single forced round.
		lastMismatch dshProfileMismatch
	)
	for {
		select {
		case <-ctx.Done():
			return
		case <-versionTicker.C:
			d.refreshAgentVersions(ctx)
		case now := <-ticker.C:
			// Forced by disagreement between two live states, not by a change
			// since the last look: a profile removed between two observations,
			// or before the first one — which is what a restart produces —
			// would otherwise never be noticed. Observed in practice: a profile
			// removed a minute after startup stayed live for three minutes and
			// the server routed a chat task straight into it.
			mismatch := d.dshRuntimeProfileMismatch()
			force := mismatch.forcesEveryTick() || (mismatch != dshMismatchNone && mismatch != lastMismatch)
			lastMismatch = mismatch
			d.convergeAgentRuntimes(ctx, &backoff, &nextRetry, now, force)
		case <-d.agentDiscoveryKick:
			// A local state change (the DSH runtime profile appearing) makes a
			// provider registrable right now. Wait for nothing: the scheduled
			// attempt this replaces can be agentConvergeMaxBackoff away.
			d.convergeAgentRuntimes(ctx, &backoff, &nextRetry, time.Now(), true)
		}
	}
}

func (d *Daemon) runWSHeartbeatSender(ctx context.Context, runtimeIDs []string, writes chan<- *wsOutbound) {
	d.sendWSHeartbeats(ctx, runtimeIDs, writes)
	interval := d.cfg.HeartbeatInterval
	if interval <= 0 {
		interval = 15 * time.Second
	}
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			d.sendWSHeartbeats(ctx, runtimeIDs, writes)
		}
	}
}

func (s *TaskService) ReportProgress(ctx context.Context, taskID string, workspaceID string, summary string, step, total int) {
	s.Bus.Publish(events.Event{
		Type:        protocol.EventTaskProgress,
		WorkspaceID: workspaceID,
		ActorType:   "system",
		ActorID:     "",
		TaskID:      taskID,
		Payload: protocol.TaskProgressPayload{
			TaskID:  taskID,
			Summary: summary,
			Step:    step,
			Total:   total,
		},
	})
}

func (c *Client) completeTaskWithRetrySchedule(ctx context.Context, taskID, output, branchName, sessionID, workDir string, sessionRolloutMissing bool, retiredSessionID, durableWorkDir string, schedule []time.Duration) error {
	body := map[string]any{"output": output}
	if branchName != "" {
		body["branch_name"] = branchName
	}
	if sessionID != "" {
		body["session_id"] = sessionID
	}
	if workDir != "" {
		body["work_dir"] = workDir
	}
	if durableWorkDir != "" {
		body["durable_work_dir"] = durableWorkDir
	}
	if sessionRolloutMissing {
		body["session_rollout_missing"] = true
	}
	if retiredSessionID != "" {
		body["retired_session_id"] = retiredSessionID
	}
	return c.postJSONWithRetry(ctx, fmt.Sprintf("/api/daemon/tasks/%s/complete", taskID), body, nil, schedule)
}

func (c *Client) failTaskWithRetrySchedule(ctx context.Context, taskID, errMsg, sessionID, workDir, branchName, failureReason string, sessionRolloutMissing bool, retiredSessionID, durableWorkDir string, schedule []time.Duration) error {
	body := map[string]any{"error": errMsg}
	if sessionID != "" {
		body["session_id"] = sessionID
	}
	if workDir != "" {
		body["work_dir"] = workDir
	}
	if durableWorkDir != "" {
		body["durable_work_dir"] = durableWorkDir
	}
	// A failed run can still have delivered a branch: worktree mode commits
	// whatever the agent left before removing the worktree, so partial work
	// survives — but only if its name travels with the failure report.
	if branchName != "" {
		body["branch_name"] = branchName
	}
	if failureReason != "" {
		body["failure_reason"] = failureReason
	}
	if sessionRolloutMissing {
		body["session_rollout_missing"] = true
	}
	if retiredSessionID != "" {
		body["retired_session_id"] = retiredSessionID
	}
	return c.postJSONWithRetry(ctx, fmt.Sprintf("/api/daemon/tasks/%s/fail", taskID), body, nil, schedule)
}

func (d *Daemon) tokenRenewalLoop(ctx context.Context) {
	ticker := time.NewTicker(DefaultTokenRenewalInterval)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			d.tryRenewToken(ctx)
		}
	}
}

func (d *Daemon) runRuntimeHeartbeat(ctx context.Context, rid string) {
	interval := d.cfg.HeartbeatInterval
	if interval <= 0 {
		interval = 15 * time.Second
	}
	// Jittered initial delay; cap at the interval so the first beat still
	// happens within one period.
	if jitter := time.Duration(rand.Int63n(int64(interval))); jitter > 0 {
		select {
		case <-ctx.Done():
			return
		case <-time.After(jitter):
		}
	}

	consecutiveTransientFailures := 0
	tick := func() {
		if d.runHeartbeatTick(ctx, rid) {
			consecutiveTransientFailures++
			if consecutiveTransientFailures == 2 {
				d.client.CloseIdleConnections()
			}
			return
		}
		consecutiveTransientFailures = 0
	}

	tick()

	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			tick()
		}
	}
}

func (d *Daemon) tryBeginServerUpdate(ctx context.Context) serverUpdateAcquireResult {
	if !d.updating.CompareAndSwap(false, true) {
		return serverUpdateAlreadyRunning
	}

	d.claimMu.Lock()
	if d.pauseClaims || d.activeTasks.Load() > 0 {
		d.claimMu.Unlock()
		d.updating.Store(false)
		return serverUpdateRuntimeBusy
	}
	d.pauseClaims = true
	d.claimMu.Unlock()

	ticker := time.NewTicker(10 * time.Millisecond)
	defer ticker.Stop()
	for {
		d.claimMu.Lock()
		if d.claimsInFlight == 0 {
			if d.activeTasks.Load() == 0 {
				d.claimMu.Unlock()
				return serverUpdateAcquired
			}
			d.pauseClaims = false
			d.claimMu.Unlock()
			d.updating.Store(false)
			return serverUpdateRuntimeBusy
		}
		d.claimMu.Unlock()

		select {
		case <-ctx.Done():
			d.releaseClaimBarrier()
			d.updating.Store(false)
			return serverUpdateRuntimeBusy
		case <-ticker.C:
		}
	}
}

func (d *Daemon) watchTaskCancellation(ctx context.Context, taskID string, pollInterval time.Duration, taskLog *slog.Logger) <-chan struct{} {
	cancelled := make(chan struct{})
	// Subscribe to the reconcile broadcaster before launching the inner
	// goroutine. A WS reconnect that fires between the goroutine starting
	// and its first notify() call would otherwise be dropped; the ticker
	// still bounds the worst case, but the whole point of the broadcast is
	// to avoid waiting on that ticker.
	var reconcileCh <-chan struct{}
	if d.reconcile != nil {
		reconcileCh = d.reconcile.notify()
	}
	go func() {
		ticker := time.NewTicker(pollInterval)
		defer ticker.Stop()
		check := func() bool {
			status, err := d.client.GetTaskStatus(ctx, taskID)
			if !shouldInterruptAgent(status, err) {
				return false
			}
			if err != nil {
				taskLog.Info("task gone server-side, interrupting agent", "error", err)
			} else {
				taskLog.Info("task reached terminal state server-side, interrupting agent", "status", status)
			}
			close(cancelled)
			return true
		}
		for {
			select {
			case <-ctx.Done():
				return
			case <-reconcileCh:
				// Refresh the subscription before issuing the request so a
				// second broadcast that overlaps GetTaskStatus is not lost.
				if d.reconcile != nil {
					reconcileCh = d.reconcile.notify()
				}
				if check() {
					return
				}
			case <-ticker.C:
				if check() {
					return
				}
			}
		}
	}()
	return cancelled
}

func (d *Daemon) handleTask(ctx context.Context, task Task, slot int) {
	d.mu.Lock()
	rt, tracked := d.runtimeIndex[task.RuntimeID]
	d.mu.Unlock()
	// The runtime can go offline between the batch claim leaving with its ID and
	// the claimed task arriving here — a below-minimum demotion or a drift
	// convergence to zero both drop rows while a claim is in flight. Reporting it
	// as runtime_offline is what the server already retries on; without this the
	// zero-value Runtime carries an empty provider and the task dies several
	// hundred lines later as `no agent configured for provider ""`, which reads
	// like a misconfigured host and is not retried.
	if !tracked {
		d.logger.Warn("claimed task targets a runtime this daemon no longer hosts; failing it back for retry",
			"task", task.ID, "runtime_id", task.RuntimeID)
		if err := d.reportTerminalTask(ctx, terminalTaskReport{
			kind:          terminalTaskReportFail,
			taskID:        task.ID,
			errorMessage:  "runtime went offline before the run started",
			failureReason: taskfailure.ReasonRuntimeOffline.String(),
		}); err != nil {
			d.logger.Error("fail task callback failed", "task", task.ID, "error", err)
		}
		return
	}
	provider := rt.Provider

	// Task-scoped logger. The task id goes in whole: it is the key every
	// other surface prints (task JSON, env-root ownership manifest, server
	// logs), so a full id is what lets a log line be joined to them. An
	// 8-char prefix cannot — task ids are UUIDv7, whose leading 32 bits are
	// a millisecond timestamp that only advances every ~65s, so concurrent
	// tasks routinely share one (#7326).
	taskLog := d.logger.With("task", task.ID)
	phaseRecorder := newTaskPhaseRecorder(taskLog.With("task_id", task.ID, "runtime_id", task.RuntimeID), time.Now)
	ctx = withTaskPhaseRecorder(ctx, phaseRecorder)
	phaseRecorder.Mark(taskPhaseClaimed)
	defer phaseRecorder.Mark(taskPhaseFinished)
	agentName := "agent"
	if task.Agent != nil {
		agentName = task.Agent.Name
	}
	if task.ChatSessionID != "" {
		taskLog.Info("picked chat task", "chat_session", task.ChatSessionID, "agent", agentName, "provider", provider)
	} else {
		taskLog.Info("picked task", "issue", task.IssueID, "agent", agentName, "provider", provider)
	}
	taskLog.Debug("task context",
		"workspace_id", task.WorkspaceID,
		"runtime_id", task.RuntimeID,
		"agent_id", task.AgentID,
		"repos", len(task.Repos),
		"project_id", task.ProjectID,
		"autopilot_run_id", task.AutopilotRunID,
		"trigger_comment_id", task.TriggerCommentID,
		"resume_session", task.PriorSessionID != "",
		"reuse_workdir", task.PriorWorkDir != "",
	)

	// If the task targets a project_resource of type local_directory that
	// is pinned to this daemon, acquire the path mutex before runner.run
	// so the server-side state machine is dispatched →
	// waiting_local_directory → running rather than backwards-transitioning
	// from running into the wait state. The release is deferred so a panic
	// or early return always frees the lock for the next waiter.
	//
	// StartTask itself now lives in runTask (see issue #3999 race A) and
	// fires only after execenv.Prepare/Reuse has put env.WorkDir on disk,
	// so consumers that read status==running can resolve the workdir path
	// without racing the daemon's os.MkdirAll.
	localRelease, abort := d.acquireLocalDirectoryLockIfNeeded(ctx, task, taskLog)
	if abort {
		return
	}
	if localRelease != nil {
		defer localRelease()
	}

	// Hold a process-wide active-root guard for the rest of this task so
	// the GC loop never sees a window where the env root has neither the
	// in-process guard nor .gc_meta.json (issue #3999 race B). runTask
	// installs its own ref-counted mark/unmark internally; without this
	// outer guard the inner unmark fires when runTask returns, leaving
	// the directory protected only by the 72h orphan TTL through
	// reportTaskResult and execenv.WriteGCMeta below. markActiveEnvRoot
	// is reference-counted, so the duplicate marks runTask installs are
	// correctly nested within these.
	resolvedEnvRoot, resolveRootErr := execenv.ResolveRootDir(taskRootDirParams(d.cfg.WorkspacesRoot, task))
	if resolveRootErr != nil {
		taskLog.Error("resolve stable task env root", "error", resolveRootErr)
	}
	if resolvedEnvRoot != "" {
		defer d.markActiveEnvRoot(resolvedEnvRoot)()
	}
	if task.PriorWorkDir != "" {
		if priorRoot := filepath.Dir(task.PriorWorkDir); priorRoot != "" && priorRoot != resolvedEnvRoot {
			defer d.markActiveEnvRoot(priorRoot)()
		}
	}

	// Create a cancellable context so we can interrupt the running agent
	// when the server signals the task should stop — either the task reached
	// a terminal state (completed/failed/cancelled) or the task row is
	// deleted (404).
	runCtx, runCancel := context.WithCancel(ctx)
	defer runCancel()

	// Poll interval is d.cancelPollInterval (5s in production, reduced in tests
	// via direct field override). Guard against zero so a misconfigured daemon
	// doesn't panic time.NewTicker.
	pollInterval := d.cancelPollInterval
	if pollInterval == 0 {
		pollInterval = 5 * time.Second
	}
	cancelledByPoll := d.watchTaskCancellation(runCtx, task.ID, pollInterval, taskLog)
	go func() {
		select {
		case <-cancelledByPoll:
			runCancel()
		case <-runCtx.Done():
		}
	}()

	result, err := d.runner.run(runCtx, task, provider, slot, taskLog)
	if errors.Is(err, errStartClaimRejected) {
		// The row belongs to another claim (or is terminal). A task-id-only
		// failure callback from this stale delivery could kill its new owner.
		taskLog.Info("discarding rejected start claim", "error", err)
		return
	}
	if result.FailureReason == taskfailure.ReasonProcessCleanupUnconfirmed.String() && err != nil {
		result.Comment += "; " + err.Error()
		err = nil // Cleanup uncertainty must outrank worktree-finalization errors.
	}

	// Shutdown cancels ctx before the runner returns. Keep the final usage,
	// server-cancellation check and acknowledgement deliverable during cleanup.
	finalCtx, finalCancel := context.WithTimeout(context.WithoutCancel(ctx), terminalTaskReportTimeout)
	defer finalCancel()

	// Report usage before any early return — the agent accumulates tokens
	// whether the task completes, errors, or is cancelled mid-run by the poll
	// goroutine. Both claude.go and codex.go populate result.Usage even when
	// runCtx is cancelled, so dropping this on the cancelled path silently
	// under-reports billing.
	if len(result.Usage) > 0 {
		if usageErr := d.client.ReportTaskUsage(finalCtx, task.ID, result.Usage); usageErr != nil {
			taskLog.Warn("report task usage failed", "error", usageErr)
		}
	}

	// Check if we were cancelled by the polling goroutine.
	select {
	case <-cancelledByPoll:
		taskLog.Info("task cancelled during execution, discarding result",
			"branch_name", result.BranchName, "error", err)
		// runner.run has returned, so the transcript flush is complete —
		// tell the server it can settle its deferred chat finalization
		// (#5219). The sweeper grace period covers a lost ack's chat settle,
		// but NOT the payload: the branch rides along because the worktree was
		// already finalized before this check, and when Finalize instead
		// ABORTED, the preserved-worktree error is the only pointer left to
		// the agent's work — everything else on this path is discarded. Other
		// run errors stay discarded: on a cancelled run they are expected
		// noise (context canceled, killed process), and persisting them would
		// stamp a bogus reason on every ordinary mid-run cancel.
		// RetiredSessionID rides along too: a resumed session the run never
		// got a single message out of must not stay this issue's resume
		// pointer (MUL-8188).
		ack := taskCancelAcknowledgement(result, err, provider)
		if ackErr := d.client.AckTaskCancelled(finalCtx, task.ID, ack); ackErr != nil {
			taskLog.Warn("cancel ack failed; server sweeper will finalize", "error", ackErr)
		}
		return
	default:
	}

	if err != nil {
		taskLog.Error("task failed", "error", err)
		// runTask may have reached worktree finalization before returning the
		// error. Preserve any delivery metadata that defer attached to the named
		// result, especially the actual/preserved workdir and delivered branch.
		// MUL-2946: route the bare error string through the canonical
		// classifier so the failure_reason column reflects the actual
		// shape of the failure (provider 5xx, network, process crash,
		// …) rather than the coarse legacy "agent_error" bucket.
		if failErr := d.reportTerminalTask(ctx, terminalTaskReport{
			kind:             terminalTaskReportFail,
			taskID:           task.ID,
			errorMessage:     err.Error(),
			branchName:       result.BranchName,
			workDir:          result.WorkDir,
			durableWorkDir:   result.DurableWorkDir,
			failureReason:    taskRunFailureReason(err),
			retiredSessionID: result.RetiredSessionID,
		}); failErr != nil {
			taskLog.Error("fail task callback failed", "error", failErr)
		}
		return
	}

	_ = d.client.ReportProgress(finalCtx, task.ID, "Finishing task", 2, 2)

	// Final pre-completion check: if the server already moved the task to a
	// terminal state (completed/failed/cancelled) or deleted the row
	// outright, skip reporting — the complete/fail callbacks would fail
	// anyway. Reuse shouldInterruptAgent so this guard honors the same
	// signals as the in-flight watcher.
	if status, err := d.client.GetTaskStatus(finalCtx, task.ID); shouldInterruptAgent(status, err) {
		taskLog.Info("task cancelled during execution, discarding result",
			"status", status, "error", err, "branch_name", result.BranchName)
		// Same contract as the poll-cancelled path above: the transcript is
		// flushed, so let the server settle its deferred chat finalization, and
		// carry the finalized branch so cancelled work stays discoverable. No
		// error to carry here — this branch is only reached with err == nil.
		// This fires for ANY observed terminal status; the server applies the
		// payload only to a cancelled row (status CAS), because for
		// completed/failed rows the complete/fail callback is the
		// authoritative channel and a stale run's late ack must not touch
		// them.
		if ackErr := d.client.AckTaskCancelled(finalCtx, task.ID, taskCancelAcknowledgement(result, nil, provider)); ackErr != nil {
			taskLog.Warn("cancel ack failed; server sweeper will finalize", "error", ackErr)
		}
		return
	}

	// Only the parent (daemon) context identifies shutdown. A cancelled agent
	// with a live parent remains a deliberate cancellation; server terminal
	// states and poll cancellation have already taken precedence above.
	// Infrastructure interruptions carry a diagnostic, matching server-side orphan
	// recovery; deliberate cancellation relies on its localized reason label.
	if result.Status == "cancelled" && result.FailureReason == "" && errors.Is(ctx.Err(), context.Canceled) {
		result.FailureReason = taskfailure.ReasonRuntimeRecovery.String()
		result.Comment = "daemon shut down while task was in flight"
	}

	d.reportTaskResult(ctx, task.ID, result, taskLog)

	// Write GC metadata after the task finishes so the periodic GC loop
	// can look up the parent record (issue / chat session / autopilot run /
	// task itself for quick-create) later. Written last so that a mid-task
	// crash leaves the directory as an orphan (cleaned up by GCOrphanTTL).
	if result.EnvRoot != "" {
		if meta, ok := gcMetaForTask(task); ok {
			// A local_directory project_resource matched this daemon
			// means the agent ran in the user's own tree. Stamp the
			// meta so the GC loop never tries to RemoveAll envRoot's
			// sibling workdir (which is the user's path) or the envRoot
			// itself (we want output/ and logs/ to linger for forensic
			// access).
			//
			// Worktree mode is excluded: its workdir is a disposable
			// worktree INSIDE envRoot, already removed by Finalize, and
			// the deliverable lives on as a branch in the user's repo.
			// Stamping it would hand every worktree task a permanently
			// exempt env root, so the directory would accumulate one env
			// root per task forever — the exact cost the exemption was
			// meant to trade away for a user's own files.
			if assignment, _ := localDirectoryAssignmentForTask(task, d.cfg.DaemonID); assignment != nil && !assignment.UsesWorktree() {
				meta.LocalDirectory = true
			}
			if err := execenv.WriteGCMeta(result.EnvRoot, meta, taskLog); err != nil {
				taskLog.Warn("write gc meta failed (non-fatal)", "error", err)
			}
			if meta.Kind == execenv.GCKindIssue && !meta.LocalDirectory {
				d.environments.reportDeclared(ctx, task.ID, result.EnvRoot)
			}
		}
	}
}

func (d *Daemon) sendTerminalTaskReport(ctx context.Context, report terminalTaskReport, schedule []time.Duration) error {
	if d.terminalReportSend != nil {
		return d.terminalReportSend(ctx, report, schedule)
	}
	switch report.kind {
	case terminalTaskReportComplete:
		return d.client.completeTaskWithRetrySchedule(ctx, report.taskID, report.output, report.branchName, report.sessionID, report.workDir, report.sessionRolloutMissing, report.retiredSessionID, report.durableWorkDir, schedule)
	case terminalTaskReportFail:
		return d.client.failTaskWithRetrySchedule(ctx, report.taskID, report.errorMessage, report.sessionID, report.workDir, report.branchName, report.failureReason, report.sessionRolloutMissing, report.retiredSessionID, report.durableWorkDir, schedule)
	default:
		return fmt.Errorf("unsupported terminal task report kind %d", report.kind)
	}
}

func waitCodexRolloutPresent(ctx context.Context, codexHome, sessionID string) bool {
	if codexHome == "" || sessionID == "" {
		return true
	}
	if execenv.CodexResumeRolloutPresent(codexHome, sessionID) {
		return true
	}
	ticker := time.NewTicker(codexRolloutPollInterval)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			// The rollout may have landed just as the run ended — check once more.
			return execenv.CodexResumeRolloutPresent(codexHome, sessionID)
		case <-ticker.C:
			if execenv.CodexResumeRolloutPresent(codexHome, sessionID) {
				return true
			}
		}
	}
}

func (d *Daemon) startTaskPrepareLeaseExtender(ctx context.Context, task Task, taskLog *slog.Logger) func() {
	refresh := d.prepareLeaseRefresh
	if refresh <= 0 {
		refresh = taskPrepareLeaseRefresh
	}
	leaseCtx, cancel := context.WithCancel(ctx)
	done := make(chan struct{})
	go func() {
		defer close(done)
		ticker := time.NewTicker(refresh)
		defer ticker.Stop()
		for {
			select {
			case <-leaseCtx.Done():
				return
			case <-ticker.C:
				reqCtx, reqCancel := context.WithTimeout(leaseCtx, taskPrepareLeaseTimeout)
				err := d.client.ExtendTaskPrepareLease(reqCtx, task.RuntimeID, task.ID)
				reqCancel()
				if err != nil {
					taskLog.Warn("extend task prepare lease failed", "error", err)
				}
			}
		}
	}()

	var once sync.Once
	return func() {
		once.Do(func() {
			cancel()
			<-done
		})
	}
}

func (d *Daemon) startUsageFlush(ctx context.Context, taskID string, live *atomic.Value, taskLog *slog.Logger) (stop func()) {
	done := make(chan struct{})
	stopped := make(chan struct{})
	go func() {
		defer close(stopped)
		ticker := time.NewTicker(liveUsageFlushEvery)
		defer ticker.Stop()
		var reported string
		for {
			select {
			case <-done:
				return
			case <-ctx.Done():
				return
			case <-ticker.C:
				select {
				case <-done:
					return
				case <-ctx.Done():
					return
				default:
				}
				entries, _ := live.Load().([]TaskUsageEntry)
				if len(entries) == 0 {
					continue
				}
				// An idle agent costs nothing: re-posting the numbers the server
				// already has is traffic, not information.
				key := fmt.Sprintf("%v", entries)
				if key == reported {
					continue
				}
				// Preserve ordering with the terminal report even when the run is
				// cancelled. The HTTP timeout still bounds an in-flight request.
				if err := d.client.ReportTaskUsageSnapshot(context.WithoutCancel(ctx), taskID, entries); err != nil {
					// Not fatal — the terminal report carries the run's usage
					// again if a flush is lost.
					taskLog.Warn("live usage flush failed", "error", err)
					continue
				}
				reported = key
			}
		}
	}()
	return sync.OnceFunc(func() {
		close(done)
		// Let an in-flight POST finish before the terminal overwrite. Cancelling
		// only the client request can return before the server finishes writing.
		// The control-plane HTTP client's timeout bounds this wait.
		<-stopped
	})
}

func (d *Daemon) executeAndDrain(ctx context.Context, backend agent.Backend, prompt string, opts agent.ExecOptions, taskLog *slog.Logger, taskID, codexHome string, msgSeq *atomic.Int32) (finalResult agent.Result, finalTools int32, finalErr error) {
	defer func() {
		if finalResult.Status == "cleanup_unconfirmed" {
			d.cleanupUnconfirmed.Store(true)
		}
	}()
	phaseRecorder := taskPhaseRecorderFromContext(ctx)
	// Wrap the caller's ctx so the idle watchdog (below) can interrupt both
	// the agent subprocess (via the ctx passed to backend.Execute) AND the
	// drain loop with a single cancel. Without this layer the backend would
	// stay tied to the parent ctx and our cancellation could only abort
	// drain, leaving the subprocess running.
	agentCtx, agentCancel := context.WithCancel(ctx)
	defer agentCancel()

	session, err := backend.Execute(agentCtx, prompt, opts)
	if err != nil {
		// One provider-agnostic boundary for launches: every backend's
		// cmd.Start() failure arrives here, so diagnosing ENOEXEC at this point
		// covers claude, opencode and any CLI added later without a wrap in
		// each backend (MUL-6164).
		err = agent.ExplainExecError(err)
		taskLog.Debug("backend execute returned error", "error", err)
		return agent.Result{}, 0, err
	}
	// This counter intentionally starts at the narrower provider-session
	// boundary, not at the earlier server-side StartTask transition.
	d.runningTasks.Add(1)
	defer d.runningTasks.Add(-1)
	phaseRecorder.Mark(taskPhaseRuntimeStarted)
	outputObserver := taskOutputObserverFromContext(ctx)
	outputObserver.begin()
	taskLog.Debug("backend started, draining messages")

	// Only negotiated sessions may claim additions. Stop and join delivery
	// before the caller reports the task's terminal state to the server.
	if opts.EnableTaskSupplement && session.Supplement != nil && session.SupplementReady != nil {
		supplementCtx, cancelSupplements := context.WithCancel(agentCtx)
		supplementsDone := make(chan struct{})
		wakeup, unsubscribe := d.taskSupplementSignals.subscribe(taskID)
		go func() {
			defer unsubscribe()
			defer close(supplementsDone)
			d.runTaskSupplementLoop(supplementCtx, session, taskID, wakeup, taskLog)
		}()
		defer func() {
			cancelSupplements()
			<-supplementsDone
		}()
	}

	// Bound the drain loop only when there is a wall-clock cap. With a positive
	// opts.Timeout, give the drain a slightly longer deadline than the backend
	// so it can still collect the backend's own timeout Result if the scanner
	// is stuck on a hung stdout pipe (the extra 30 s covers cleanup after the
	// backend's own deadline fires). With no cap (opts.Timeout <= 0) the
	// inactivity watchdog is the only liveness net, so the drain must NOT
	// impose its own deadline either — otherwise an actively streaming long run
	// would be cut off here regardless of progress (MUL-3064).
	var drainCtx context.Context
	var drainCancel context.CancelFunc
	if opts.Timeout > 0 {
		drainCtx, drainCancel = context.WithTimeout(agentCtx, opts.Timeout+30*time.Second)
	} else {
		drainCtx, drainCancel = context.WithCancel(agentCtx)
	}
	defer drainCancel()

	var toolCount atomic.Int32
	// lastActivityAt records (as awakeclock nanos) when the drain loop most
	// recently received a message from the backend. The idle watchdog
	// reads this to decide whether the agent has gone silent for too long.
	// It is an awake-time reading, not wall time, so a host suspend is never
	// charged to the agent as silence (GitHub #9024).
	// Initialise to the start so a backend that never emits a single
	// message also trips the watchdog.
	var lastActivityAt atomic.Int64
	lastActivityAt.Store(int64(awakeclock.Now()))
	// inFlightTools counts tool_use messages that haven't yet been paired
	// with a matching tool_result. A non-zero count means the agent is
	// legitimately waiting on a tool (e.g. `npm install`, `docker build`)
	// that may run far longer than the idle window without emitting any
	// message — so while a tool is in flight the watchdog applies the larger
	// AgentToolWatchdog budget instead of treating that silence as a hang.
	var inFlightTools atomic.Int32
	var idleWatchdogFired atomic.Bool
	// idleWatchdogThreshold records (as nanos) which silence budget actually
	// tripped the watchdog — the idle window or the larger in-flight-tool
	// window — so the failure message reports the real duration.
	idleWindow := d.cfg.AgentIdleWatchdog
	// A provider may opt into a shorter per-run no-message budget. The global
	// zero remains authoritative so WORKPAL_AGENT_IDLE_WATCHDOG=0 still disables
	// the entire watchdog suite. Tool calls continue to use AgentToolWatchdog.
	if idleWindow > 0 && opts.IdleWatchdogTimeout > 0 && opts.IdleWatchdogTimeout < idleWindow {
		idleWindow = opts.IdleWatchdogTimeout
	}
	var idleWatchdogThreshold atomic.Int64
	idleWatchdogThreshold.Store(int64(idleWindow))
	watchdogToolCount := inFlightTools.Load
	if session.ToolActivity != nil {
		watchdogToolCount = func() int32 {
			count, at := session.ToolActivity()
			for {
				previous := lastActivityAt.Load()
				if int64(at) <= previous || lastActivityAt.CompareAndSwap(previous, int64(at)) {
					break
				}
			}
			return count
		}
	}
	// A backend that can prove its outcome is already decided outranks every
	// liveness policy below: a run whose terminal result has been read is not a
	// hang, no matter how long its cleanup then takes.
	// Nil is meaningful and kept distinguishable: a backend that offers no
	// terminal boundary is one whose result cannot outrank a force stop, so it
	// must not be given a hand-off window it can never use. Every such backend
	// keeps the previous behaviour, including a wedged one, which is force
	// stopped and classified without waiting for anything.
	handsOverTerminal := session.TerminalObserved != nil
	terminalObserved := session.TerminalObserved
	if terminalObserved == nil {
		terminalObserved = func() bool { return false }
	}
	watchdogCtx, stopWatchdog := context.WithCancel(agentCtx)
	defer stopWatchdog()
	if idleWindow > 0 {
		go d.runIdleWatchdog(watchdogCtx, idleWindow, d.cfg.AgentToolWatchdog, &lastActivityAt, watchdogToolCount, &idleWatchdogFired, &idleWatchdogThreshold, agentCancel, session.Messages, session.InterruptBackgroundTools, terminalObserved, taskLog)
	}

	// drainFinished closes after the drain goroutine has flushed the last
	// message batch, so the result hand-off below can wait for the transcript
	// tail to be persisted.
	drainFinished := make(chan struct{})
	go func() {
		defer close(drainFinished)
		var mu sync.Mutex
		var pendingContent strings.Builder
		var pendingType string
		var pendingAt time.Time
		var batch []TaskMessageData
		callIDToTool := map[string]string{}
		// Provider IDs can restart on a same-task retry (for example item_0).
		// Allocate opaque transcript IDs per execution, including orphan results,
		// so neither a retry nor a missing call can steal another call's result.
		transcriptCallIDs := map[string]string{}
		transcriptCallID := func(providerID string) string {
			if providerID == "" {
				return ""
			}
			if id, ok := transcriptCallIDs[providerID]; ok {
				return id
			}
			id := uuid.NewString()
			transcriptCallIDs[providerID] = id
			return id
		}

		// sealPendingLocked turns the current contiguous text/thinking frame
		// into a sequenced row. Callers hold mu so a ticker flush cannot assign
		// a later seq between sealing the frame and appending the event that
		// followed it.
		sealPendingLocked := func() {
			if pendingContent.Len() == 0 {
				return
			}
			s := msgSeq.Add(1)
			batch = append(batch, TaskMessageData{
				Seq:       int(s),
				Type:      pendingType,
				Content:   pendingContent.String(),
				CreatedAt: pendingAt,
			})
			pendingContent.Reset()
			pendingType = ""
			pendingAt = time.Time{}
		}

		appendPending := func(messageType, content string, observedAt time.Time) {
			if content == "" {
				return
			}
			mu.Lock()
			defer mu.Unlock()
			if pendingType != "" && pendingType != messageType {
				sealPendingLocked()
			}
			if pendingContent.Len() == 0 {
				pendingType = messageType
				pendingAt = observedAt
			}
			pendingContent.WriteString(content)
		}

		flush := func() {
			mu.Lock()
			sealPendingLocked()
			toSend := batch
			batch = nil
			mu.Unlock()

			if len(toSend) > 0 {
				sendCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
				if err := d.client.ReportTaskMessages(sendCtx, taskID, toSend); err != nil {
					taskLog.Debug("failed to report task messages", "error", err)
				} else {
					taskLog.Debug("reported task messages", "count", len(toSend), "last_seq", toSend[len(toSend)-1].Seq)
				}
				cancel()
			}
		}

		ticker := time.NewTicker(500 * time.Millisecond)
		defer ticker.Stop()

		done := make(chan struct{})
		tickerDone := make(chan struct{})
		firstVisible := make(chan struct{}, 1)
		go func() {
			defer close(tickerDone)
			for {
				select {
				case <-ticker.C:
					flush()
				case <-firstVisible:
					flush()
				case <-done:
					return
				}
			}
		}()
		// The periodic flush bounds request rate for the rest of the transcript,
		// but making the first visible event wait for its next 500 ms edge adds
		// pure presentation latency. Signal at most once per execution; a buffered
		// channel keeps the drain loop non-blocking while the reporter is busy.
		var firstVisibleOnce sync.Once
		flushFirstVisible := func() {
			firstVisibleOnce.Do(func() {
				firstVisible <- struct{}{}
			})
		}

		var sessionPinned atomic.Bool
		for {
			select {
			case msg, ok := <-session.Messages:
				if !ok {
					goto drainDone
				}
				if isTaskOutputReceived(msg) {
					phaseRecorder.Mark(taskPhaseFirstOutputReceived)
					outputObserver.markOutput()
				}
				if isTaskToolUse(msg) {
					phaseRecorder.Mark(taskPhaseFirstToolUse)
				}
				// Stamp activity as soon as a message lands. The idle
				// watchdog reads this to decide whether the backend has
				// gone silent — stamping before processing makes sure a
				// slow downstream call (mu.Lock contention, batch resize)
				// can't be misattributed to backend silence.
				observedAt := time.Now().UTC()
				lastActivityAt.Store(int64(awakeclock.Now()))
				switch msg.Type {
				case agent.MessageStatus:
					// Persist the session/work_dir as soon as the backend
					// reveals them. Without this, a daemon crash mid-run
					// loses the resume pointer and the auto-retry fires
					// without context.
					// MUL-5305: pin the resume pointer only once the session's
					// rollout is actually in the store, so a crash-recovery pointer
					// the daemon cannot resume never poisons the next follow-up
					// (FailAgentTask keeps the pinned session_id via COALESCE, so a
					// bad mid-flight pin survives a later terminal failure). Codex
					// reveals the session id on a single task_started status, so a
					// background waiter polls for the rollout for the life of the
					// run and pins the moment it lands — a rollout that flushes
					// after this status is still pinned in-flight (crash recovery
					// preserved), while a session whose rollout never lands is never
					// pinned. The terminal report is the authoritative writer.
					// Non-Codex providers (codexHome == "") pin immediately.
					if msg.SessionID != "" && !sessionPinned.Swap(true) {
						sid := msg.SessionID
						wd := opts.Cwd
						go func() {
							if !waitCodexRolloutPresent(drainCtx, codexHome, sid) {
								taskLog.Debug("skip pinning codex session: rollout not present before run ended",
									"session_id", sid, "codex_home", codexHome)
								return
							}
							pinCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
							defer cancel()
							if err := d.client.PinTaskSession(pinCtx, taskID, sid, wd); err != nil {
								taskLog.Debug("pin session failed", "error", err)
							}
						}()
					}
				case agent.MessageToolUse:
					n := toolCount.Add(1)
					inFlightTools.Add(1)
					taskLog.Info(fmt.Sprintf("tool #%d: %s", n, msg.Tool))
					mu.Lock()
					sealPendingLocked()
					if msg.CallID != "" {
						callIDToTool[msg.CallID] = msg.Tool
					}
					s := msgSeq.Add(1)
					batch = append(batch, TaskMessageData{
						Seq:       int(s),
						Type:      "tool_use",
						CallID:    transcriptCallID(msg.CallID),
						Tool:      msg.Tool,
						CreatedAt: observedAt,
						// Redact before the payload leaves this process, not
						// only on arrival. The server redacts again in its
						// ingest handler, but that is the *remote* side: a
						// daemon that self-updated ahead of the server — or one
						// talking to a server mid-rollout — would otherwise ship
						// whole-file edit contents (a deleted .env, a patched
						// credential) to a peer that does not scrub nested
						// values yet. Deployment order is not a control we
						// have, so this side has to be safe on its own.
						Input: redact.InputMap(msg.Input),
					})
					mu.Unlock()
					flushFirstVisible()
				case agent.MessageToolResult:
					// Decrement only when the count would stay >= 0. A stray
					// tool_result with no matching tool_use (backend bug or
					// reconnect mid-stream) shouldn't push the counter
					// negative — that would re-arm the watchdog one tool_use
					// too early on the next call.
					for {
						cur := inFlightTools.Load()
						if cur <= 0 {
							break
						}
						if inFlightTools.CompareAndSwap(cur, cur-1) {
							break
						}
					}
					output, outputTruncated := toolOutputPreview(msg.Output)
					mu.Lock()
					sealPendingLocked()
					toolName := msg.Tool
					if toolName == "" && msg.CallID != "" {
						toolName = callIDToTool[msg.CallID]
					}
					s := msgSeq.Add(1)
					taskLog.Info("tool_result observed", "seq", s, "tool", toolName, "call_id", msg.CallID)
					batch = append(batch, TaskMessageData{
						Seq:       int(s),
						Type:      "tool_result",
						CallID:    transcriptCallID(msg.CallID),
						Tool:      toolName,
						Output:    output,
						CreatedAt: observedAt,
						// Always sent, including false: the reader has to be
						// able to tell "this record is complete" from "this
						// record predates the flag", and only a daemon that
						// measured the output can say the former.
						OutputTruncated: &outputTruncated,
					})
					mu.Unlock()
					flushFirstVisible()
				case agent.MessageThinking:
					appendPending("thinking", msg.Content, observedAt)
					if msg.Content != "" {
						flushFirstVisible()
					}
				case agent.MessageText:
					if msg.Content != "" {
						taskLog.Debug("agent", "text", truncateLog(msg.Content, 200))
					}
					appendPending("text", msg.Content, observedAt)
					if msg.Content != "" {
						flushFirstVisible()
					}
				case agent.MessageError:
					taskLog.Error("agent error", "content", msg.Content)
					mu.Lock()
					sealPendingLocked()
					s := msgSeq.Add(1)
					batch = append(batch, TaskMessageData{
						Seq:       int(s),
						Type:      "error",
						Content:   msg.Content,
						CreatedAt: observedAt,
					})
					mu.Unlock()
					flushFirstVisible()
				}
			case <-drainCtx.Done():
				goto drainDone
			}
		}
	drainDone:
		close(done)
		// Let any tick-driven flush finish before the final one: a flush still
		// in flight would otherwise keep posting batches after this goroutine
		// signalled that the transcript tail was persisted.
		<-tickerDone
		flush()
	}()

	// waitForDrain blocks until the drain goroutine has flushed the transcript
	// tail, so every terminal return below hands control back only after the
	// task's reported messages are persisted — a consumer reading them at the
	// terminal transition would otherwise see a transcript that is non-empty
	// but truncated, indistinguishable from a complete one. Bounded so a
	// backend that never closes its message channel cannot stall the terminal
	// transition: after 10s the drain loop is cancelled and given a window
	// wide enough for its worst-case exit — an in-flight tick flush plus the
	// final one, each capped by the 5s ReportTaskMessages timeout and neither
	// interruptible by the cancel (they post on context.Background()).
	waitForDrain := func() {
		select {
		case <-drainFinished:
		case <-time.After(10 * time.Second):
			drainCancel()
			select {
			case <-drainFinished:
			case <-time.After(12 * time.Second):
				taskLog.Warn("transcript drain did not stop after cancel; completing anyway")
			}
		}
	}
	// awaitTerminalResult gives a backend that advertises an authoritative
	// terminal boundary one bounded chance to hand over its result after a
	// cancellation won the outer select. Result delivery is the linearization
	// point: TerminalObserved must be published before that send, so checking it
	// afterwards preserves a provider outcome without racing a flag read. A
	// delivered non-authoritative result is still returned to the idle-watchdog
	// caller for re-tagging; ordinary upstream cancellation deliberately ignores
	// it and keeps the existing generic cancelled disposition.
	awaitTerminalResult := func(trigger string) (result agent.Result, delivered, authoritative bool) {
		if !handsOverTerminal {
			return agent.Result{}, false, false
		}
		if trigger == "idle_watchdog" {
			// Keep this event stable: besides operator diagnostics, the terminal
			// race regression uses it as the hand-off linearization probe.
			taskLog.Info("idle watchdog fired; waiting for the backend to hand over its result",
				"budget", terminalResultHandoffBudget.String())
		} else {
			taskLog.Info("waiting for the backend to hand over its result after cancellation",
				"trigger", trigger,
				"budget", terminalResultHandoffBudget.String())
		}
		timer := time.NewTimer(terminalResultHandoffBudget)
		defer timer.Stop()
		select {
		case result, ok := <-session.Result:
			if !ok {
				return agent.Result{}, false, false
			}
			return result, true, terminalObserved()
		case <-timer.C:
			if trigger == "idle_watchdog" {
				taskLog.Warn("backend did not hand over a result within the budget; classifying by liveness",
					"budget", terminalResultHandoffBudget.String())
			} else {
				taskLog.Warn("backend did not hand over a result within the budget; classifying by cancellation trigger",
					"trigger", trigger,
					"budget", terminalResultHandoffBudget.String())
			}
			return agent.Result{}, false, false
		}
	}
	cleanupUnconfirmed := func() (agent.Result, int32, error) {
		return agent.Result{
			Status: "cleanup_unconfirmed",
			Error:  "Runtime did not confirm process cleanup; background processes may still be running. Check them before manually rerunning this task.",
		}, toolCount.Load(), nil
	}

	select {
	case result, ok := <-session.Result:
		stopWatchdog()
		waitForDrain()
		if !ok && session.CleanupRequired {
			return cleanupUnconfirmed()
		}
		// terminalObserved outranks a watchdog that fired anyway: if the backend
		// had already read its authoritative result, this is the real outcome and
		// re-tagging it would report a completed run as a hang.
		if idleWatchdogFired.Load() && !terminalObserved() && result.Status != "cleanup_unconfirmed" {
			// The backend's wait goroutine (e.g. claude.go) translates the
			// SIGKILL we delivered via agentCancel into Status="aborted".
			// Re-tag it as "idle_watchdog" so runTask routes the
			// disposition through a dedicated failure_reason, not the
			// generic "agent_error" bucket the aborted path falls into.
			result.Status = "idle_watchdog"
			if result.Error == "" {
				result.Error = idleWatchdogReason(time.Duration(idleWatchdogThreshold.Load()))
			}
		}
		return result, toolCount.Load(), nil
	case <-drainCtx.Done():
		// The drain loop is exiting on this same Done signal; wait for its
		// final flush so the timeout/watchdog/cancel terminals below cannot
		// hand back (and let runTask fail-and-broadcast) a still-flushing
		// transcript either.
		waitForDrain()
		// Idle watchdog cancels via agentCancel(), which propagates here as
		// context.Canceled. Check this BEFORE the generic cancelled/timeout
		// classifiers so a watchdog-induced stop isn't misreported as a
		// server cancellation.
		if idleWatchdogFired.Load() {
			// For a backend that publishes a terminal boundary, enter the
			// hand-off without asking terminalObserved first. Reading a flag and
			// then acting on it is exactly the window this branch kept losing:
			// the backend can publish between the read and the classifier below.
			// Waiting for the result instead makes its delivery the
			// linearization point, and the backend contract — publish the
			// observation before sending Result — is what makes the check after
			// delivery reliable rather than lucky.
			//
			// Such a backend always closes Result, so a wedged one still ends
			// this wait promptly through the closed channel rather than the
			// budget.
			if result, delivered, authoritative := awaitTerminalResult("idle_watchdog"); authoritative {
				// The backend had already read its authoritative result, so
				// this is the real outcome, not a hang.
				return result, toolCount.Load(), nil
			} else if delivered {
				if result.Status == "cleanup_unconfirmed" {
					return result, toolCount.Load(), nil
				}
				// The backend's wait goroutine (e.g. claude.go) translates the
				// SIGKILL we delivered via agentCancel into Status="aborted".
				// Re-tag it so runTask routes the disposition through the
				// dedicated liveness failure_reason.
				result.Status = "idle_watchdog"
				if result.Error == "" {
					result.Error = idleWatchdogReason(time.Duration(idleWatchdogThreshold.Load()))
				}
				return result, toolCount.Load(), nil
			}
			if session.CleanupRequired {
				return cleanupUnconfirmed()
			}
			return agent.Result{
				Status: "idle_watchdog",
				Error:  idleWatchdogReason(time.Duration(idleWatchdogThreshold.Load())),
			}, toolCount.Load(), nil
		}
		// Distinguish external cancellation (e.g. server-initiated cancel
		// because the issue was reassigned, or the user invoked CancelTask)
		// from genuine drain-deadline timeouts. context.Canceled means the
		// upstream runCtx fired runCancel(); context.DeadlineExceeded is the
		// drain deadline expiring on its own.
		if errors.Is(drainCtx.Err(), context.Canceled) {
			if result, delivered, authoritative := awaitTerminalResult("upstream_context"); authoritative || (delivered && result.Status == "cleanup_unconfirmed") {
				return result, toolCount.Load(), nil
			} else if session.CleanupRequired && !delivered {
				return cleanupUnconfirmed()
			}
			return agent.Result{
				Status: "cancelled",
				Error:  "task cancelled by upstream context (server cancel or daemon shutdown)",
			}, toolCount.Load(), nil
		}
		if session.CleanupRequired {
			agentCancel()
			if result, delivered, _ := awaitTerminalResult("drain_timeout"); delivered {
				return result, toolCount.Load(), nil
			}
			return cleanupUnconfirmed()
		}
		return agent.Result{
			Status: "timeout",
			Error:  "agent did not produce result within drain timeout",
		}, toolCount.Load(), nil
	}
}

func (d *Daemon) runIdleWatchdogWithClock(agentCtx context.Context, window, toolWindow time.Duration, lastActivityAt *atomic.Int64, inFlightTools func() int32, fired *atomic.Bool, firedThreshold *atomic.Int64, cancel context.CancelFunc, messages <-chan agent.Message, interruptBackground func() bool, terminalObserved func() bool, taskLog *slog.Logger, awakeNow func() time.Duration) {
	tickWindow := window
	if toolWindow > 0 && toolWindow < tickWindow {
		tickWindow = toolWindow
	}
	ticker := time.NewTicker(idleWatchdogTickInterval(tickWindow))
	defer ticker.Stop()
	for {
		select {
		case <-agentCtx.Done():
			return
		case <-ticker.C:
			// Pick the silence budget. A tool in flight is expected to be
			// silent (a long build/install/test emits nothing between
			// tool_use and tool_result), so it gets the larger toolWindow;
			// toolWindow <= 0 disables the in-flight bound entirely.
			threshold := window
			toolInFlight := inFlightTools() > 0
			if toolInFlight {
				if toolWindow <= 0 {
					continue
				}
				threshold = toolWindow
			}
			last := lastActivityAt.Load()
			idleFor := awakeNow() - time.Duration(last)
			if idleFor < threshold {
				continue
			}
			// A buffered-but-undrained message means the drain loop is
			// behind, not the backend. Wait one more tick rather than
			// killing a backend that is still producing output.
			if len(messages) > 0 {
				continue
			}
			// Cursor can stop its owned background tools without aborting the
			// agent. The same watchdog owns both the budget and this recovery,
			// so no competing timer can cancel Cursor while it reports a result.
			if agentCtx.Err() != nil {
				return
			}
			if terminalObserved != nil && terminalObserved() {
				return
			}
			if toolInFlight && interruptBackground != nil && interruptBackground() {
				lastActivityAt.Store(int64(awakeNow()))
				taskLog.Info("tool watchdog stopped background tools; waiting for agent result")
				continue
			}
			// A natural tool completion may race the callback or the tick.
			if agentCtx.Err() != nil {
				return
			}
			// Refresh native tool activity BEFORE reading its timestamp. The
			// callback may publish newer activity without changing the count.
			currentToolInFlight := inFlightTools() > 0
			currentActivity := lastActivityAt.Load()
			if currentActivity != last ||
				currentToolInFlight != toolInFlight || len(messages) > 0 {
				continue
			}
			if agentCtx.Err() != nil {
				return
			}
			// Last gate before force-stopping. The terminal result can land while
			// this tick is deciding — including while it is blocked inside the
			// interrupt callback above — and a decided outcome is never a hang.
			if terminalObserved != nil && terminalObserved() {
				return
			}
			// No "task" field here: taskLog already carries the full id.
			taskLog.Warn("idle watchdog firing: no agent activity, force-stopping run",
				"idle_for", idleFor.Round(time.Second).String(),
				"threshold", threshold.String(),
				"tool_in_flight", toolInFlight,
			)
			firedThreshold.Store(int64(threshold))
			fired.Store(true)
			cancel()
			return
		}
	}
}

func (d *Daemon) startRateLimitFlush(ctx context.Context, taskID string, taskLog *slog.Logger) (observe func(agent.RateLimitSnapshot), stop func()) {
	reporter := &rateLimitReporter{
		post: func(ctx context.Context, s agent.RateLimitSnapshot) error {
			return d.client.ReportTaskRateLimits(ctx, taskID, s)
		},
		log: taskLog,
	}
	done := make(chan struct{})
	stopped := make(chan struct{})
	go func() {
		defer close(stopped)
		ticker := time.NewTicker(rateLimitFlushEvery)
		defer ticker.Stop()
		for {
			select {
			case <-done:
				return
			case <-ctx.Done():
				return
			case <-ticker.C:
				reporter.flush(context.WithoutCancel(ctx))
			}
		}
	}()
	return reporter.observe, sync.OnceFunc(func() {
		close(done)
		<-stopped
		reporter.flush(context.WithoutCancel(ctx))
	})
}

func (m *Manager) WaitReady(ctx context.Context, key string) Environment {
	ticker := time.NewTicker(250 * time.Millisecond)
	defer ticker.Stop()
	for {
		m.mu.Lock()
		var view Environment
		for _, e := range m.envs {
			if "config:"+e.rec.ID == key {
				view = m.viewLocked(e)
			}
		}
		m.mu.Unlock()
		if view.State != StateStarting {
			return view
		}
		select {
		case <-ctx.Done():
			return view
		case <-ticker.C:
		}
	}
}

func AcquireCodexSessionWriterLock(ctx context.Context, store string, onWait func()) (*CodexSessionWriterLock, error) {
	if store == "" {
		return nil, nil
	}
	if err := ctx.Err(); err != nil {
		return nil, err
	}

	path := codexSessionWriterLockPath(store)
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return nil, fmt.Errorf("create Codex session writer lock directory: %w", err)
	}
	f, err := openLockFile(path)
	if err != nil {
		return nil, fmt.Errorf("open Codex session writer lock %s: %w", path, err)
	}

	announced := false
	ticker := time.NewTicker(codexSessionWriterLockPoll)
	defer ticker.Stop()
	for {
		locked, lockErr := lockFileExclusiveNonBlocking(f)
		if lockErr != nil {
			_ = f.Close()
			return nil, fmt.Errorf("lock Codex session store %s: %w", store, lockErr)
		}
		if locked {
			return &CodexSessionWriterLock{file: f}, nil
		}
		if !announced {
			announced = true
			if onWait != nil {
				onWait()
			}
		}
		select {
		case <-ctx.Done():
			_ = f.Close()
			return nil, fmt.Errorf("wait for Codex session writer lock: %w", ctx.Err())
		case <-ticker.C:
		}
	}
}

func (s *IssueWakeupService) publishWakeupActivities(activities ...wakeupActivity) {
	if s.Tasks == nil || s.Tasks.Bus == nil {
		return
	}
	for _, a := range activities {
		if !a.row.ID.Valid {
			continue
		}
		s.Tasks.Bus.Publish(events.Event{
			Type: protocol.EventActivityCreated, WorkspaceID: util.UUIDToString(a.row.WorkspaceID),
			ActorType: a.actorType, ActorID: a.actorID,
			Payload: map[string]any{
				"issue_id": util.UUIDToString(a.row.IssueID),
				"entry": map[string]any{
					"type": "activity", "id": util.UUIDToString(a.row.ID),
					"actor_type": a.actorType, "actor_id": a.actorID, "action": a.row.Action,
					"details": a.details, "created_at": a.row.CreatedAt.Time.UTC().Format(time.RFC3339Nano),
				},
			},
		})
	}
}

func (s *TaskService) SupplementChatQuickActions(ctx context.Context, task db.AgentTaskQueue, raw string, failed bool) error {
	if !task.ChatSessionID.Valid {
		return nil
	}
	actions := parseChatQuickActionsOutput(raw)
	for i := range actions {
		actions[i].Label = redact.Text(actions[i].Label)
		actions[i].Prompt = redact.Text(actions[i].Prompt)
	}

	var msg db.ChatMessage
	var err error
	if len(actions) > 0 {
		encoded, marshalErr := json.Marshal(actions)
		if marshalErr != nil {
			return fmt.Errorf("marshal chat quick actions: %w", marshalErr)
		}
		msg, err = s.Queries.SetChatMessageQuickActionsByTask(ctx, db.SetChatMessageQuickActionsByTaskParams{
			TaskID:       task.ID,
			QuickActions: encoded,
		})
	} else {
		msg, err = s.Queries.GetChatMessageByTaskAssistant(ctx, task.ID)
	}
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil
		}
		return fmt.Errorf("attach chat quick actions: %w", err)
	}

	scope := s.ResolveTaskScope(ctx, task)
	workspaceID := scope.WorkspaceID
	if workspaceID == "" {
		return nil
	}
	payload := protocol.ChatQuickActionsPayload{
		ChatSessionID: util.UUIDToString(task.ChatSessionID),
		TaskID:        util.UUIDToString(task.ID),
		MessageID:     util.UUIDToString(msg.ID),
		QuickActions:  []protocol.ChatQuickAction{},
		Failed:        failed,
	}
	_ = json.Unmarshal(msg.QuickActions, &payload.QuickActions)
	s.Bus.Publish(events.Event{
		Type:               protocol.EventChatQuickActions,
		WorkspaceID:        workspaceID,
		ActorType:          "system",
		ActorID:            "",
		ChatSessionID:      util.UUIDToString(task.ChatSessionID),
		ChatSessionOwnerID: scope.ChatSessionOwnerID,
		Payload:            payload,
	})
	return nil
}

func (s *AutopilotService) dispatchAutopilotRun(
	ctx context.Context,
	autopilot db.Autopilot,
	triggerID pgtype.UUID,
	source string,
	run *db.AutopilotRun,
	actorUserID pgtype.UUID,
) (*db.AutopilotRun, dispatch.ReasonCode, error) {
	if err := s.guardAutopilotProjectAccess(ctx, autopilot, run, actorUserID); err != nil {
		if skipped, code := s.handleDispatchSkip(ctx, autopilot, run, err); skipped != nil {
			return skipped, code, nil
		}
		s.failRun(ctx, run.ID, err.Error())
		s.captureAutopilotRunFailed(autopilot, *run, source, err.Error())
		return run, dispatch.ReasonInternalError, fmt.Errorf("check project access: %w", err)
	}
	switch autopilot.ExecutionMode {
	case "create_issue":
		triggerTimezone := s.resolveAutopilotTriggerTimezone(ctx, triggerID)
		err := s.dispatchCreateIssue(ctx, autopilot, run, triggerTimezone, actorUserID)
		// Same rule as IssueService.Create: a collision on uq_issue_workspace_number
		// means the workspace counter trails MAX(issue.number), and the failed
		// dispatch already rolled its own increment back. Heal, then dispatch once
		// more — otherwise this run fails and every later dispatch of this autopilot
		// fails with it, which is how one drifted workspace wedges a board.
		if err != nil && healIssueCounterAfterCollision(ctx, s.Queries, autopilot.WorkspaceID, err) {
			err = s.dispatchCreateIssue(ctx, autopilot, run, triggerTimezone, actorUserID)
		}
		if errors.Is(err, errWebhookRunAlreadyDispatched) {
			return run, "", s.ensureWebhookCreateIssueTask(ctx, autopilot, *run)
		}
		if run.WebhookDeliveryID.Valid && errors.Is(err, ErrDuplicatePendingTask) {
			err = nil // The recovery worker already enqueued this issue's task.
		}
		if err != nil {
			if skipped, code := s.handleDispatchSkip(ctx, autopilot, run, err); skipped != nil {
				return skipped, code, nil
			}
			s.failRun(ctx, run.ID, err.Error())
			s.captureAutopilotRunFailed(autopilot, *run, source, err.Error())
			return run, dispatchFailReasonCode(err), fmt.Errorf("dispatch create_issue: %w", err)
		}
	case "run_only":
		if err := s.dispatchRunOnly(ctx, autopilot, run, actorUserID); err != nil {
			if skipped, code := s.handleDispatchSkip(ctx, autopilot, run, err); skipped != nil {
				return skipped, code, nil
			}
			s.failRun(ctx, run.ID, err.Error())
			s.captureAutopilotRunFailed(autopilot, *run, source, err.Error())
			return run, dispatchFailReasonCode(err), fmt.Errorf("dispatch run_only: %w", err)
		}
	default:
		s.failRun(ctx, run.ID, "unknown execution_mode: "+autopilot.ExecutionMode)
		s.captureAutopilotRunFailed(autopilot, *run, source, "unknown execution_mode: "+autopilot.ExecutionMode)
		return run, dispatch.ReasonInternalError, fmt.Errorf("unknown execution_mode: %s", autopilot.ExecutionMode)
	}

	// Update last_run_at on the autopilot.
	s.Queries.UpdateAutopilotLastRunAt(ctx, autopilot.ID)

	// Publish run start event.
	s.Bus.Publish(events.Event{
		Type:        protocol.EventAutopilotRunStart,
		WorkspaceID: util.UUIDToString(autopilot.WorkspaceID),
		ActorType:   "system",
		Payload: map[string]any{
			"run_id":       util.UUIDToString(run.ID),
			"autopilot_id": util.UUIDToString(autopilot.ID),
			"source":       source,
			"status":       run.Status,
		},
	})

	return run, "", nil
}

func (s *AutopilotService) dispatchCreateIssue(ctx context.Context, ap db.Autopilot, run *db.AutopilotRun, triggerTimezone string, actorUserID pgtype.UUID) error {
	leader, _, err := s.resolveAutopilotLeader(ctx, ap)
	if err != nil {
		return fmt.Errorf("resolve leader: %w", err)
	}
	tx, err := s.TxStarter.Begin(ctx)
	if err != nil {
		return fmt.Errorf("begin tx: %w", err)
	}
	defer tx.Rollback(ctx)

	qtx := s.Queries.WithTx(tx)

	title := s.interpolateTemplate(ap, *run, triggerTimezone)
	description := s.buildIssueDescription(ap, *run, triggerTimezone)

	// Refresh the autopilot row at dispatch time so we use the current project
	// binding instead of any stale snapshot the caller may have cached.
	currentAutopilot, err := qtx.GetAutopilotInWorkspace(ctx, db.GetAutopilotInWorkspaceParams{
		ID:          ap.ID,
		WorkspaceID: ap.WorkspaceID,
	})
	if err != nil {
		return fmt.Errorf("refresh autopilot: %w", err)
	}
	projectID := currentAutopilot.ProjectID

	if run.WebhookDeliveryID.Valid {
		// A reclaimed delivery can overlap its previous worker. Serialize on
		// the run so both workers observe the same committed issue link.
		if err := qtx.LockIssueDuplicateKey(ctx, util.UUIDToString(run.ID)); err != nil {
			return fmt.Errorf("lock webhook run: %w", err)
		}
		current, err := qtx.GetAutopilotRun(ctx, run.ID)
		if err != nil {
			return fmt.Errorf("reload webhook run: %w", err)
		}
		if isAutopilotRunComplete(current) {
			*run = current
			return errWebhookRunAlreadyDispatched
		}
	} else if duplicate, found, err := issueguard.LockAndFindRecentAutopilotDuplicate(
		ctx, qtx, ap.WorkspaceID, ap.ID, projectID, title, autopilotRecentDuplicateWindow,
	); err != nil {
		return fmt.Errorf("recent duplicate guard: %w", err)
	} else if found {
		return &errDispatchSkipped{reason: "recent duplicate autopilot issue: " + util.UUIDToString(duplicate.ID), code: dispatch.ReasonAlreadyActive}
	}

	issueNumber, err := qtx.IncrementIssueCounter(ctx, ap.WorkspaceID)
	if err != nil {
		return fmt.Errorf("increment issue counter: %w", err)
	}

	newPosition, err := issueposition.NextTopPosition(ctx, tx, ap.WorkspaceID, "todo")
	if err != nil {
		return fmt.Errorf("get next issue position: %w", err)
	}

	issue, err := qtx.CreateIssueWithOrigin(ctx, db.CreateIssueWithOriginParams{
		ID:           dbid.NewV7(),
		WorkspaceID:  ap.WorkspaceID,
		Title:        title,
		Description:  description,
		Status:       "todo",
		Priority:     "none",
		AssigneeType: pgtype.Text{String: ap.AssigneeType, Valid: true},
		AssigneeID:   ap.AssigneeID,
		// The agent that the autopilot dispatches to is the issue's creator,
		// not the human who originally configured the autopilot. The latter
		// is captured separately via origin_type=autopilot + origin_id. For
		// squad-assigned autopilots, the creator is the resolved leader —
		// the same agent the issue listener will end up enqueueing.
		CreatorType:   "agent",
		CreatorID:     leader.ID,
		ParentIssueID: pgtype.UUID{},
		Position:      newPosition,
		StartDate:     pgtype.Date{},
		DueDate:       pgtype.Date{},
		Number:        issueNumber,
		ProjectID:     projectID,
		OriginType:    pgtype.Text{String: "autopilot", Valid: true},
		OriginID:      ap.ID,
	})
	if err != nil {
		return classifyIssueNumberCollision(fmt.Errorf("create issue: %w", err), issueNumber)
	}

	// Fan out the default subscriber template inside the same tx as the
	// issue insert, before EventIssueCreated fires — so notification
	// listeners see the full subscriber set on the first event instead of
	// racing the listener that would otherwise hydrate the template.
	templateSubs, err := qtx.ListAutopilotSubscribers(ctx, ap.ID)
	if err != nil {
		return fmt.Errorf("list autopilot subscribers: %w", err)
	}
	for _, sub := range templateSubs {
		if _, err := qtx.AddIssueSubscriber(ctx, db.AddIssueSubscriberParams{
			IssueID:  issue.ID,
			UserType: sub.UserType,
			UserID:   sub.UserID,
			Reason:   "autopilot",
		}); err != nil {
			return fmt.Errorf("add autopilot subscriber to issue: %w", err)
		}
	}

	// Link the run inside the same tx as the issue insert. This makes the
	// recent-duplicate guard count only fully observable autopilot issues and
	// avoids a crash window where recovery would see an orphan issue but no
	// linked run.
	updatedRun, err := qtx.UpdateAutopilotRunIssueCreated(ctx, db.UpdateAutopilotRunIssueCreatedParams{
		ID:      run.ID,
		IssueID: issue.ID,
	})
	if err != nil {
		return fmt.Errorf("link run to issue: %w", err)
	}
	*run = updatedRun
	if _, err := settleAutopilotQuota(ctx, qtx, run.QuotaReservationID, true); err != nil {
		return fmt.Errorf("consume quota reservation: %w", err)
	}

	if err := tx.Commit(ctx); err != nil {
		return fmt.Errorf("commit tx: %w", err)
	}

	// Publish issue:created so the existing event chain fires
	// (subscriber listeners, activity listeners, notification listeners). For
	// squad autopilots, this is what triggers shouldEnqueueSquadLeaderOnAssign
	// → enqueueSquadLeaderTask — no separate squad-routing code needed here.
	prefix := s.getIssuePrefix(ap.WorkspaceID)
	s.Bus.Publish(events.Event{
		Type:        protocol.EventIssueCreated,
		WorkspaceID: util.UUIDToString(ap.WorkspaceID),
		ActorType:   "agent",
		ActorID:     util.UUIDToString(leader.ID),
		Payload: map[string]any{
			"issue": IssueToMapResolved(ctx, s.Queries, issue, prefix),
		},
	})
	s.captureIssueCreatedFromAutopilot(ap, run, issue, leader.ID)

	// The issue:created notification listener only handles handler.IssueResponse
	// payloads and only direct-notifies the assignee + @mentions; subscribers
	// don't get an inbox at creation time on the manual path because there are
	// none yet. The autopilot path is different: the template subscribers were
	// fanned out into issue_subscriber inside the tx above, so they exist at the
	// moment of creation and OQ3 says they should receive the same subscription
	// events as reason='manual'. Issue creation is one such event — so write
	// the inbox rows directly here. Done after commit so a failure here doesn't
	// roll back the issue itself.
	s.notifyAutopilotSubscribersOnCreate(ctx, ap, issue, leader.ID, templateSubs)

	// Enqueue agent task via the existing flow. Squad-assigned autopilots
	// route to the resolved leader as the executing agent (Path A from
	// MUL-2429); agent-assigned autopilots go through the standard issue
	// path. Both code paths land in agent_task_queue with agent_id = leader.
	// A MANUAL trigger (valid actorUserID) is a direct human action: enqueue via the
	// actor-carrying entry points so attribution resolves direct_human to the
	// triggering member (originator == accountable == actor, MUL-4302 §4). Schedule /
	// webhook dispatch has no actor and takes the plain entry points, where the
	// autopilot-origin issue resolves to the trigger's created_by principal
	// (MUL-6951). The *ByActor variants are the actor-carrying enqueue methods.
	var dispatchTask db.AgentTaskQueue
	if ap.AssigneeType == "squad" {
		// Fail-closed invocation gate: verify the admission principal (manual
		// clicker, else the trigger's created_by — see autopilotAdmitInvoke) may
		// still invoke the leader. Catches configs that predate the save-time
		// gate, and configs that no longer pass (MUL-3963 / MUL-4525).
		if !s.autopilotAdmitInvoke(ctx, ap, leader, actorUserID, run.TriggerID) {
			return fmt.Errorf("not allowed to invoke private squad leader")
		}
		if actorUserID.Valid {
			if dispatchTask, err = s.TaskSvc.EnqueueTaskForSquadLeaderByActor(ctx, issue, leader.ID, ap.AssigneeID, actorUserID); err != nil {
				return fmt.Errorf("enqueue squad leader task: %w", err)
			}
		} else if dispatchTask, err = s.TaskSvc.EnqueueTaskForSquadLeader(ctx, issue, leader.ID, ap.AssigneeID, pgtype.UUID{}, OriginDerived); err != nil {
			return fmt.Errorf("enqueue squad leader task: %w", err)
		}
	} else if actorUserID.Valid {
		if dispatchTask, err = s.TaskSvc.EnqueueTaskForIssueByActor(ctx, issue, actorUserID); err != nil {
			return fmt.Errorf("enqueue task for issue: %w", err)
		}
	} else if dispatchTask, err = s.TaskSvc.EnqueueTaskForIssue(ctx, issue); err != nil {
		return fmt.Errorf("enqueue task for issue: %w", err)
	}
	s.linkDispatchTask(ctx, run, dispatchTask)

	slog.Info("autopilot dispatched (create_issue)",
		"autopilot_id", util.UUIDToString(ap.ID),
		"assignee_type", ap.AssigneeType,
		"issue_id", util.UUIDToString(issue.ID),
		"leader_id", util.UUIDToString(leader.ID),
		"run_id", util.UUIDToString(run.ID),
	)
	return nil
}

