func (s *TaskService) createAgentComment(ctx context.Context, issueID, agentID pgtype.UUID, content, commentType string, parentID, sourceTaskID pgtype.UUID) {
	if content == "" {
		return
	}
	// Look up issue to get workspace ID for mention expansion and broadcasting.
	issue, err := s.Queries.GetIssue(ctx, issueID)
	if err != nil {
		return
	}
	// Resolve the thread root for thread-level side effects without overwriting
	// parentID. The stored parent_id must remain the exact comment being replied
	// to; recursive thread reads recover the root when needed.
	var rootComment *db.Comment
	if parentID.Valid {
		if root, err := s.Queries.GetThreadRoot(ctx, db.GetThreadRootParams{
			CommentID:   parentID,
			WorkspaceID: issue.WorkspaceID,
		}); err == nil {
			rootComment = &root
		}
	}
	created, err := s.Queries.CreateComment(ctx, db.CreateCommentParams{
		ID:           dbid.NewV7(),
		IssueID:      issueID,
		WorkspaceID:  issue.WorkspaceID,
		AuthorType:   "agent",
		AuthorID:     agentID,
		Content:      content,
		Type:         commentType,
		ParentID:     parentID,
		SourceTaskID: sourceTaskID,
	})
	if err != nil {
		return
	}
	comment := created.Comment()
	commentFields := commentEventFields(comment)
	commentFields["revision"] = comment.Revision
	s.Bus.Publish(events.Event{
		Type:        protocol.EventCommentCreated,
		WorkspaceID: util.UUIDToString(issue.WorkspaceID),
		ActorType:   "agent",
		ActorID:     util.UUIDToString(agentID),
		Payload: map[string]any{
			"comment":        commentFields,
			"issue_title":    issue.Title,
			"issue_status":   issue.Status,
			"issue_revision": created.IssueRevision,
		},
	})
	s.AutoUnresolveThreadOnReply(ctx, rootComment, util.UUIDToString(issue.WorkspaceID), "agent", util.UUIDToString(agentID), sourceTaskID)
}

func (s *TaskService) AutoUnresolveThreadOnReply(ctx context.Context, parent *db.Comment, workspaceID, actorType, actorID string, sourceTaskID pgtype.UUID) {
	if parent == nil || !parent.ResolvedAt.Valid {
		return
	}
	// This follow-up write is a consequence of the reply's run, not a new
	// system action. Preserve that lineage for event subscriptions as well.
	tx, err := s.TxStarter.Begin(ctx)
	if err != nil {
		slog.Warn("auto-unresolve transaction failed", "error", err)
		return
	}
	defer tx.Rollback(ctx)
	_, err = tx.Exec(ctx, `SELECT set_config('workpal.actor_type',$1,true),set_config('workpal.actor_id',$2,true),set_config('workpal.source_task_id',$3,true)`, actorType, actorID, util.UUIDToString(sourceTaskID))
	if err != nil {
		slog.Warn("auto-unresolve source attribution failed", "error", err)
		return
	}
	updated, err := s.Queries.WithTx(tx).UnresolveComment(ctx, parent.ID)
	if err != nil {
		slog.Warn("auto-unresolve on reply failed", "error", err, "comment_id", util.UUIDToString(parent.ID))
		return
	}
	if err := tx.Commit(ctx); err != nil {
		slog.Warn("auto-unresolve commit failed", "error", err)
		return
	}
	s.Bus.Publish(events.Event{
		Type:        protocol.EventCommentUnresolved,
		WorkspaceID: workspaceID,
		ActorType:   actorType,
		ActorID:     actorID,
		Payload: map[string]any{
			"comment": map[string]any{
				"id":               util.UUIDToString(updated.ID),
				"issue_id":         util.UUIDToString(updated.IssueID),
				"author_type":      updated.AuthorType,
				"author_id":        util.UUIDToString(updated.AuthorID),
				"content":          updated.Content,
				"type":             updated.Type,
				"parent_id":        util.UUIDToPtr(updated.ParentID),
				"created_at":       util.TimestampToString(updated.CreatedAt),
				"updated_at":       util.TimestampToString(updated.UpdatedAt),
				"resolved_at":      util.TimestampToPtr(updated.ResolvedAt),
				"resolved_by_type": util.TextToPtr(updated.ResolvedByType),
				"resolved_by_id":   util.UUIDToPtr(updated.ResolvedByID),
				"revision":         updated.Revision,
			},
		},
	})
}

func NextOccurrenceAfterUTC(cronExpr, timezone string, after time.Time) (time.Time, error) {
	sched, loc, err := parseCronSchedule(cronExpr, timezone)
	if err != nil {
		return time.Time{}, err
	}
	return sched.Next(after.In(loc)).UTC(), nil
}

func NextOccurrencesAfterUTC(cronExpr, timezone string, after time.Time, count int) ([]time.Time, error) {
	sched, loc, err := parseCronSchedule(cronExpr, timezone)
	if err != nil {
		return nil, err
	}
	out := make([]time.Time, 0, count)
	cursor := after.In(loc)
	for i := 0; i < count; i++ {
		next := sched.Next(cursor)
		if next.IsZero() {
			break
		}
		out = append(out, next.UTC())
		cursor = next
	}
	return out, nil
}

func NextOccurrencesUTC(cronExpr, timezone string, after, until time.Time) ([]time.Time, error) {
	sched, loc, err := parseCronSchedule(cronExpr, timezone)
	if err != nil {
		return nil, err
	}
	const hardCap = 1024
	out := make([]time.Time, 0, 8)
	cursor := after.In(loc)
	untilLocal := until.In(loc)
	for len(out) < hardCap {
		next := sched.Next(cursor)
		if next.After(untilLocal) {
			break
		}
		out = append(out, next.UTC())
		cursor = next
	}
	return out, nil
}

func parseCronSchedule(cronExpr, timezone string) (cron.Schedule, *time.Location, error) {
	// robfig v3.0.1 reads an optional "TZ="/"CRON_TZ=" prefix up to the first
	// space and panics (parser.go:99, slice[:-1]) when that space is missing.
	// The preview endpoint feeds raw user text here, so reject the shape the
	// parser cannot survive instead of turning a typo into a 500.
	if (strings.HasPrefix(cronExpr, "TZ=") || strings.HasPrefix(cronExpr, "CRON_TZ=")) &&
		!strings.Contains(cronExpr, " ") {
		return nil, nil, fmt.Errorf("parse cron: missing schedule after timezone prefix %q", cronExpr)
	}
	sched, err := cronParser.Parse(cronExpr)
	if err != nil {
		return nil, nil, fmt.Errorf("parse cron: %w", err)
	}
	loc, err := time.LoadLocation(timezone)
	if err != nil {
		return nil, nil, fmt.Errorf("invalid timezone %q: %w", timezone, err)
	}
	return sched, loc, nil
}

func (d *PluginEventDispatcher) sweepInvocations() {
	defer d.wg.Done()
	ticker := time.NewTicker(invocationSweepEvery)
	defer ticker.Stop()
	for {
		select {
		case <-d.stop:
			return
		case <-ticker.C:
			d.sweepOnce()
		}
	}
}

func (s *PluginService) reconcilePluginHookSchedules(
	ctx context.Context,
	queries *db.Queries,
	installation db.PluginInstallation,
	manifest plugincontract.Manifest,
) error {
	existingRows, err := queries.ListPluginHookSchedulesByInstallation(ctx, installation.ID)
	if err != nil {
		return &PluginError{Kind: PluginErrorUnavailable, Message: "list plugin hook schedules", Err: err}
	}
	existing := make(map[string]db.PluginHookSchedule, len(existingRows))
	for _, row := range existingRows {
		existing[row.HookKey] = row
	}

	now := time.Now().UTC()
	for _, hook := range manifest.Contributes.Hooks {
		if hook.Schedule == nil || !HookAllowsTrigger(hook, plugincontract.TriggerSchedule) {
			continue
		}
		nextRun, err := pluginScheduleNextRun(*hook.Schedule, now)
		if err != nil {
			// Published manifests were validated already. Surfacing drift here is
			// safer than installing a schedule the runtime cannot evaluate.
			return &PluginError{Kind: PluginErrorInvalid, Message: fmt.Sprintf("schedule for hook %q is invalid", hook.Key), Err: err}
		}
		if !installation.Enabled {
			// Disabled installations have no meaningful "next" run. Re-enable
			// rotates the generation and computes this projection from that time.
			nextRun = pgtype.Timestamptz{}
		}

		row, found := existing[hook.Key]
		if !found {
			if _, err := queries.CreatePluginHookSchedule(ctx, db.CreatePluginHookScheduleParams{
				InstallationID: installation.ID,
				WorkspaceID:    installation.WorkspaceID,
				HookKey:        hook.Key,
				CronExpression: hook.Schedule.Cron,
				Timezone:       hook.Schedule.Timezone,
				Enabled:        installation.Enabled,
				NextRunAt:      nextRun,
			}); err != nil {
				return &PluginError{Kind: PluginErrorUnavailable, Message: "create plugin hook schedule", Err: err}
			}
			continue
		}
		delete(existing, hook.Key)
		if row.CronExpression == hook.Schedule.Cron && row.Timezone == hook.Schedule.Timezone {
			continue
		}
		if _, err := queries.UpdatePluginHookScheduleDefinition(ctx, db.UpdatePluginHookScheduleDefinitionParams{
			ID:             row.ID,
			CronExpression: hook.Schedule.Cron,
			Timezone:       hook.Schedule.Timezone,
			Enabled:        installation.Enabled,
			NextRunAt:      nextRun,
		}); err != nil {
			return &PluginError{Kind: PluginErrorUnavailable, Message: "update plugin hook schedule", Err: err}
		}
	}

	for _, orphan := range existing {
		if err := queries.DeletePluginHookSchedule(ctx, orphan.ID); err != nil {
			return &PluginError{Kind: PluginErrorUnavailable, Message: "delete removed plugin hook schedule", Err: err}
		}
	}
	return nil
}

func (s *PluginService) setPluginHookSchedulesEnabled(
	ctx context.Context,
	queries *db.Queries,
	installationID pgtype.UUID,
	enabled bool,
) error {
	if !enabled {
		if err := queries.DisablePluginHookSchedules(ctx, installationID); err != nil {
			return &PluginError{Kind: PluginErrorUnavailable, Message: "disable plugin hook schedules", Err: err}
		}
		return nil
	}

	rows, err := queries.ListPluginHookSchedulesByInstallation(ctx, installationID)
	if err != nil {
		return &PluginError{Kind: PluginErrorUnavailable, Message: "list plugin hook schedules", Err: err}
	}
	now := time.Now().UTC()
	for _, row := range rows {
		nextRun, err := pluginScheduleNextRun(plugincontract.HookSchedule{
			Cron: row.CronExpression, Timezone: row.Timezone,
		}, now)
		if err != nil {
			return &PluginError{Kind: PluginErrorInvalid, Message: fmt.Sprintf("schedule for hook %q is invalid", row.HookKey), Err: err}
		}
		if _, err := queries.ReactivatePluginHookSchedule(ctx, db.ReactivatePluginHookScheduleParams{
			ID:        row.ID,
			NextRunAt: nextRun,
		}); err != nil {
			return &PluginError{Kind: PluginErrorUnavailable, Message: "reactivate plugin hook schedule", Err: err}
		}
	}
	return nil
}

func (s *IssueService) publishIssueCreated(issue db.Issue, attachments []db.Attachment, labels []db.IssueLabel, creatorType, actorID string, opts IssueCreateOpts) {
	if s.Bus == nil {
		return
	}
	var payload map[string]any
	if opts.BroadcastPayload != nil {
		payload = opts.BroadcastPayload(issue, attachments, labels)
	} else {
		// Minimal fallback so cache invalidations still fire even if the
		// caller forgot to supply a builder. Front-ends that expect the
		// full IssueResponse must pass BroadcastPayload.
		payload = map[string]any{"issue_id": util.UUIDToString(issue.ID)}
	}
	s.Bus.Publish(events.Event{
		Type:        protocol.EventIssueCreated,
		WorkspaceID: util.UUIDToString(issue.WorkspaceID),
		ActorType:   creatorType,
		ActorID:     actorID,
		Payload:     payload,
	})
}

