	}
	bus.Publish(events.Event{
		Type:        protocol.EventAgentStatus,
		WorkspaceID: util.UUIDToString(agent.WorkspaceID),
		ActorType:   "system",
		Payload:     map[string]any{"agent_id": util.UUIDToString(agent.ID), "status": agent.Status},
	})
}

func markIssueUnreadForRun(ctx context.Context, bus *events.Bus, queries *db.Queries, e events.Event, outcome string) {
	payload, ok := e.Payload.(map[string]any)
	if !ok {
		return
	}
	issueID, _ := payload["issue_id"].(string)
	issueUUID, err := util.ParseUUID(issueID)
	if err != nil {
		return
	}
	agentID, _ := payload["agent_id"].(string)
	taskID, _ := payload["task_id"].(string)

	rows, err := queries.MarkIssueUnreadForSubscribers(ctx, db.MarkIssueUnreadForSubscribersParams{
		Outcome: outcome,
		AgentID: optionalUUID(agentID),
		TaskID:  optionalUUID(taskID),
		IssueID: issueUUID,
	})
	if err != nil {
		slog.Error("issue unread: failed to mark subscribers", "issue_id", issueID, "error", err)
		return
	}
	for _, row := range rows {
		workspaceID := util.UUIDToString(row.WorkspaceID)
		bus.Publish(events.Event{
			Type:        protocol.EventIssueUnreadChanged,
			WorkspaceID: workspaceID,
			ActorType:   "agent",
			ActorID:     agentID,
			Payload: map[string]any{
				"workspace_id": workspaceID,
				"recipient_id": util.UUIDToString(row.UserID),
				"issue_id":     issueID,
				"unread":       true,
			},
		})
	}
}

func runAutopilotQuotaReconciler(ctx context.Context, svc *service.AutopilotService) {
	ticker := time.NewTicker(autopilotQuotaReconcileInterval)
	defer ticker.Stop()
	for {
		now := time.Now()
		if settled, err := svc.ReconcileAutopilotQuotaReservations(
			ctx,
			now.Add(-autopilotQuotaTerminalRecoveryAge),
			now.Add(-autopilotQuotaPartialRecoveryAge),
			autopilotQuotaReconcileBatch,
		); err != nil {
			if ctx.Err() == nil {
				slog.Warn("autopilot quota reconciler failed", "error", err)
			}
		} else if settled > 0 {
			slog.Info("autopilot quota reconciler settled reservations", "count", settled)
		}
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
		}
	}
}

func runDBStatsLogger(ctx context.Context, role string, pool *pgxpool.Pool) {
	ticker := time.NewTicker(dbStatsInterval)
	defer ticker.Stop()

	var (
		lastEmpty      int64
		lastAcquire    int64
		lastAcquireDur time.Duration
		lastCanceled   int64
	)
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
		}

		s := pool.Stat()
		emptyDelta := s.EmptyAcquireCount() - lastEmpty
		acquireDelta := s.AcquireCount() - lastAcquire
		acquireDurDelta := s.AcquireDuration() - lastAcquireDur
		canceledDelta := s.CanceledAcquireCount() - lastCanceled

		// Average wait per acquire over the last sampling window. Useful
		// because cumulative AcquireDuration alone hides whether the
		// situation is improving or worsening.
		var avgAcquireMs int64
		if acquireDelta > 0 {
			avgAcquireMs = (acquireDurDelta).Milliseconds() / acquireDelta
		}

		fields := []any{
			"role", role,
			"max_conns", s.MaxConns(),
			"total_conns", s.TotalConns(),
			"acquired_conns", s.AcquiredConns(),
			"idle_conns", s.IdleConns(),
			"constructing_conns", s.ConstructingConns(),
			"acquire_count_delta", acquireDelta,
			"empty_acquire_delta", emptyDelta,
			"canceled_acquire_delta", canceledDelta,
			"avg_acquire_ms", avgAcquireMs,
		}

		if emptyDelta > 0 || canceledDelta > 0 {
			slog.Warn("db pool pressure", fields...)
		} else {
			slog.Info("db pool stats", fields...)
		}

		lastEmpty = s.EmptyAcquireCount()
		lastAcquire = s.AcquireCount()
		lastAcquireDur = s.AcquireDuration()
		lastCanceled = s.CanceledAcquireCount()
	}
}

